INSERT INTO "pages" ("id", "title", "hero_type", "hero_rich_text", "hero_media_id", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (1, 'Home', 'highImpact', '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Payload Website Template","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"type":"link","fields":{"url":"/admin","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Visit the admin dashboard","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"mode":"normal","text":" to begin managing this site''s content. The code for this template is completely open-source and can be found ","type":"text","style":"","detail":0,"format":0,"version":1},{"type":"link","fields":{"url":"https://github.com/payloadcms/payload/tree/main/templates/website","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"on our Github","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"mode":"normal","text":". ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textFormat":0}],"direction":"ltr"}}', NULL, 'Payload Website Template', NULL, 'An open-source website built with Payload and Next.js.', NULL, 0, 'home', '2025-10-24T05:19:55.690Z', '2025-10-24T05:19:55.688Z', 'published');
