INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (5, 'North Virginia is for lovers (of cascading failures)', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"So chances are you have already read about this, but from about 9pm last night I began to experience issues with logging into a bunch of services online. Turns out it was the early signs of what would become a major outage with the us-east-1 AWS region that would take out a bunch of different popular services (including Strapi Cloud, which I use for this blog lol).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It''s made me reflect on AWS as a whole. I''ve been learning about different AWS products and microservice architectures in general over the past year, as this is our primary approach with the tools and services we write at work. At this point, we are fully locked into AWS and ap-southeast-2 is our mothership. I am rolling with the big boys, so it is about time I learned how to play the game and get in line.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"While we at work don''t have any reason to deploy things in North Virginia, if there was ever a Sydney or Auckland outage we would be pretty fucked. We rely on all the popular AWS products and it makes sense - I really like using most of them in isolation like DynamoDB, Lambdas and so on. But when you start to abstract away literally everything into a million pieces, and then need a literal certification to be able to understand the 4D \"UX\" patterns of AWS then surely something is wrong. There''s no reason given the design of the internet that all these services should have gone out today because a single provider and their load balancer health check had an existential crisis (I am oversimplifying here ... just let me rant lol).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This comment that I saw on Hacker News describes this well in my opinion:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"\"The costs, performance overhead, and complexity of a modern AWS deployment are insane and so out of line with what most companies should be taking on. But hype + microservices + sunk cost, and here we are.\" ","type":"text","style":"","detail":0,"format":2,"version":1},{"mode":"normal","text":"- Rob Sanheim","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":2},{"type":"block","fields":{"id":"68fb211d86ce791a46ac0c3a","media":6,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Seems like a catch-22 in my mind. I can see the appeal of AWS scale if you as a business/company reach a certain scale - that yummy elastic compute makes a lot of sense. At the same time, at that same size the costs on your public clouds like AWS/GCP/Azure etc start to get insanely expensive. Just look at someone like 37 Signals / DHH, who has saved approximately $3.2 million USD moving from AWS to bare-metal, and did not experience any downtime because of a hiccup in North Virginia.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'North Virginia is for lovers (of cascading failures)', NULL, 'I dropped the us-east-1 basket and broke all the eggs', '2025-10-20T11:00:00.000Z', 0, 'north-virginia-is-for-lovers-of-cascading-failures', '2025-10-24T07:30:13.362Z', '2025-10-24T06:44:24.364Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (6, 'Yet another rewrite', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I’ve migrated my site yet again 😬","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This marks maybe the fifth or sixth iteration of me migrating to a new personal site stack in recent memory. When I was in university I used to have a Wordpress instance running on a Hetzner VPS, and then more recently used a wide range of serverless providers and static site generators from Jekyll, Choo, 11ty, and so on.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Late last year I had migrated to Next.js, as I had already been using it a lot at work and wanted to some more “flashy” things with my site. SSR, ISR, suspense boundaries, different API routes, and everything but the kitchen sink.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I really enjoyed making it my own, but to be honest it got a bit out of control. I was piling on features like a custom are.na client and loader that I would only use in a single page, which I’d only done as it was fun to make and interesting at the time but ultimately ended up becoming tech debt.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I did a major refactor earlier this year to try and get things under control, but I was still really unhappy with it. My site, which is meant to be my own little personal sandpit or “garden”, ended up being just a technical exercise. A dev might find it mildly interesting if they went through the repo, but beyond that I felt it had begun to lack what made my previous endeavours special: content.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Whether that’s blog posts/ramblings like this one, or small creative experiments I work on and publish in my spare time, I feel like it is important to have fun with this kind of thing. It is the content and work that should be the driving force - the tech stack could be literally a public Google Doc, it doesn’t really matter if it is for yourself.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"So, this new migration is an attempt at doing something a bit different. This site is running on SolidStart, a full stack framework built on Solid.js. It is still very new but quite simple and has a React-like syntax (while not having the same foot guns), so I’m trying to keep things fairly bare. In hindsight, it probably would have made more sense for me to go with something like Astro since it is very content driven, but 🤷","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Rather than using a Git-based CMS like Keystatic or Tina which I used on my old site, I’ve opted for a Strapi backend that serves this content via a standard RESTful API. Again, all very vanilla and nothing super custom.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I want to write and make more, and post on here like a madman. I’ve got posts that go back over 4-5 years here, but there are massive gaps and sections where I felt I was being a bit lazy with my writing. I’ve definitely neglected creative pursuits and making things, feeling as though my spare time needed to be used for something that would (in)directly translate to me becoming a better developer, but now I think I realise that’s a bit sad and naff.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Here’s to keeping at it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Yet another rewrite', NULL, 'I migrated my site yet again', '2025-10-12T11:00:00.000Z', 0, 'yet-another-rewrite', '2025-10-24T06:51:59.686Z', '2025-10-24T06:51:06.614Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (7, 'Bullish on Better Auth', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I don’t enjoying dealing with auth.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I haven’t had a great deal of experience implementing this in any projects, but I’ve used Clerk, Stack Auth, and Auth.js in the past.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Each of these solutions came with their own pros and cons. For example, Clerk made it super easy to bootstrap auth with social logins, 2FA, magic keys etc, but comes at the cost of yet another service you need to pay for, and also trusting them with your user info on their infra.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Stack Auth is actually very decent - almost as easy as Clerk whilst also being cheaper and FOSS, so there’s less vendor lock in. However, you are still having to pay them if you use their cloud, and if you’re self hosting then there are better options available.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Better like Better Auth (lol). 2FA, SSO, social logins, magic keys, passwordless login, rate limiting built in - it’s literally got it all","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Also - their docs are some of the best I’ve come across (as far as Typescript projects are concerned). It blows the Auth.js/NextAuth docs out of the water - you can read everything and get a pretty good understanding of what it can do in an afternoon. Their core features are solid, and can easily be extended with plugins that connect to your main auth.ts file.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Better Auth goes as far as dealing with user roles, teams and organisations. I’m currently working on a project at my day job which uses Cognito and user roles/types defined by hand. It is incredibly complex to write and follow, and makes me want to compare against Better Auth for implementation and complexity.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"If you haven’t given it a try yet, give it a go!","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Bullish on Better Auth', NULL, 'I don''t enjoy dealiing with auth.', '2025-06-03T12:00:00.000Z', 0, 'bullish-on-better-auth', '2025-10-24T06:53:41.286Z', '2025-10-24T06:52:30.525Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (9, 'On the idea of a creative design system', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"One of the things we do at work we writing new UI components is create unit tests and stories to validate + illustrate the functionality of what we’ve created.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It works well as a process, since it forces us to think about how components could be reused across different apps and not have it defined by specific business logic. This encourages components to be reused in the future, rather than having to reinvent the wheel with each new project.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"There are many mature examples of this in different design systems. Polaris by Shopify is one such example, which is still tightly coupled with Shopify as a product but allows anyone to see each component as a sum of smaller pieces. Something like Polaris has a tight, consistent design because of this, and you can feel how each component has had a lot of thought and effort behind it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I hadn’t known about this approach until recently, which is known by some as “atomic design”. When I was learning about UI and UX a few years back, I genuinely thought that designs systems were born out of a product, not the other way round. You would design your product first, then break it down to the component level to create your design system.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Looking at what I used to do when designing apps or tools, it seems crazy to me that I wasn’t doing this. It makes so much sense from a consistency and development point of view, and it’s evident in my early work that this was affecting me (although at the time I did not know this).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I love the idea of developing a mini design system that I can utilise for various web projects. I feel as though having the added restriction of only being able to use a select set of components would actually open up a lot of creative possibilities, and would also (hopefully) result in me being able to finish things faster.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Let’s see how it goes.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'On the idea of a creative design system', NULL, 'Thinking about ways to test my components in isolation.', '2024-09-16T12:00:00.000Z', 0, 'on-the-idea-of-a-creative-design-system', '2025-10-24T07:32:42.398Z', '2025-10-24T06:54:49.282Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (10, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2025-10-24T07:06:40.518Z', '2025-10-24T07:06:40.515Z', 'draft');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (11, '2023 highlights', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"Before I forget, I wanted to reflect on a few key moments from 2023.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"At the start of the year, I got married to my best friend in the entire world. Surrounded by family and friends, it turned out to be an awesome day. We were both grateful for how the wedding turned out, and it will remain to be the happiest moment of my life. I grateful to everyone who came and spent the day celebrating with us.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"When I returned to work I did a lot of work migrating the ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb27cff68b7cd126f043b7","type":"link","fields":{"url":"https://learn.tewahi.com/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Te Wāhi Learn","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":"website onto a new version of ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb27cff68b7cd126f043b8","type":"link","fields":{"url":"https://nextra.site/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Nextra","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":". I used the opportunity to add new content and courses onto the site, and develop new tools that could help my students make art (","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb27cff68b7cd126f043b9","type":"link","fields":{"url":"https://www.anzaaeresources.nz/collections/te-wahi-auaha-at-takapuna-grammar/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Robin and I did a talk about this at ASATA","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":"). I’m proud of the work we did, and of my ability to do this with my limited understanding of Javascript and web development. I’m hoping I can train myself in this area in the new year.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"In July, I left my job at Takapuna Grammar School and relocated to Wellington with my wife. While it was hard to move away from my family and friends, it was exciting to move to a new place and set ourselves up from scratch. We filled our Honda Fit with all our belongings and drove to our new home, trying not to bottom out the car along state highway one.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"A few months into my new job in Wellington, I picked up web analytics for the first time. While I dislike ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb27cff68b7cd126f043ba","type":"link","fields":{"url":"https://stallman.org/google.html","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Google and their practices","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", I appreciated being able to learn how to use GA4 and Looker Studio to visualise analytics data. In the future, I would love to work more in this space using more privacy respecting tools such as ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb27cff68b7cd126f043bb","type":"link","fields":{"url":"https://plausible.io/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Plausible","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":".","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"We spent Christmas and New Year’s between our respective families. I got to spend a lot of time with my nieces, visiting playgrounds and parks around Auckland. Even in the few months we’ve been away they’ve grown an incredible amount.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"I don’t have any New Year’s resolutions at the moment besides the typical things one wishes they can do more of. We want to spend more time travelling next year, and I want to continue learning and making new things. We are hoping later in the year we can go to Japan to see my family and friends there.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', '2023 highlights', NULL, 'A reflection on 2023. ', '2023-12-30T11:00:00.000Z', 0, '2023-highlights', '2025-10-24T07:18:04.038Z', '2025-10-24T07:15:11.037Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (12, 'My first developer job', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"While I’ve been helping out on small pieces here and there on top of my normal day job, two months ago I “officially” became a software developer full time.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It is something that always in the back of my mind since I was in high school, but I never pursued it seriously as I felt I wasn’t smart enough. Even the past few years where I have mostly written web apps and tools for fun, I’d always figured I was too late - that since I hadn’t started learning in my early twenties or teens that there was no point in trying.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Out of the blue I was suddenly offered the role, doing mostly stuff I had already been doing on the side with Next.js, Typescript and Express but in an official capacity. I’m hugely thankful for the opportunity, and in particular the help and support from my colleagues who have pushed me to pursue this and back myself.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am not really sure if I should shout them out in person here, don’t really know what the proper etiquette is. But in any case, it is thanks to them that I decided to start taking this seriously and pursue it as a career. I’ll be forever grateful to them for believing in me.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I still feel like an imposter now, but I suspect I always will which is okay as the uncertainty has always helped to motivate me to learn and get better (or at least to a point where I can say I’m “good enough”). I thought for the longest time in my teens and twenties that I would be an artist since that is all I knew and thought I was good at, but it turns out it is never too late to try something new.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'My first developer job', NULL, 'For the past two months, I’ve been working full time as a developer. ', '2025-04-04T11:00:00.000Z', 0, 'my-first-developer-job', '2025-10-24T07:27:06.259Z', '2025-10-24T07:26:01.632Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (13, 'New rewrite', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"After nearly 4 years of using 11ty as my static site generator, I decided to bite the bullet and give Next.js a try.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The 11ty site I had been using was originally a portfolio starter template by Piper Haywood and Sam Baldwin, the former who was kind enough to talk to me in 2020 and gave me advice on how to get started with web work as a complete newbie.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I have been using Next for a number of products that we have been building at work, so felt comfortable enough to give it a try for this site rewrite. The flexibility offered by Next and React is what got me interested in the first place. My original website wasn''t particularly feature-rich or complicated to begin with, so it wouldn''t be too difficult to try recreate this.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Having migrated all of my content and work across, the site feels noticeable faster compared to 11ty. While 11ty build times are still much, much faster by comparison, this doesn''t really affect the end user experience. Vercel takes care of the deployment, and next/image ensures that all of my images are optimised when they are sent to the viewer which is awesome.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"In the future, I want to expand the functionality of this site by creating more custom components and libraries. For example, all of the Are.na channels that I have are being rendered as iframes, so it would be great if I could leverage something like arena-ts so that this loads natively with proper image optimisation. Since iframes aren''t particularly accessible and are difficult to navigate using a keyboard, this would be a big plus as well.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"If you''re interested in seeing the code, feel free to take a look on my GitHub.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'New rewrite', NULL, 'I recently made the switch to Next.js.', '2024-06-26T12:00:00.000Z', 0, 'new-rewrite', '2025-10-24T07:29:21.233Z', '2025-10-24T07:28:00.775Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (14, 'Carterton', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"68fb2b423fff295afb4677cb","media":8,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', NULL, NULL, 'An image of the lavender farms in Carterton, Wellington.', '2024-01-13T11:00:00.000Z', 0, 'carterton', '2025-10-24T07:31:49.555Z', '2025-10-24T07:30:31.174Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (15, 'Elmet Brae', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Some of us from ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2c013fff295afb4677cc","type":"link","fields":{"url":"https://merveilles.town","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Merveilles","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", a loose collective that I''ve been part of for a while now, recently released a compilation of noise/drone/ambient music inspired by the idea of \"the land\", released for free via ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2c013fff295afb4677cd","type":"link","fields":{"url":"https://orllewin.github.io/elmet_brae/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Elmet Brae records","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" and ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2c013fff295afb4677ce","type":"link","fields":{"url":"https://beldamrecords.bandcamp.com/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Beldam","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":".","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"While I''ve worked with Merveilles on other projects before, this is the first one I''ve done involving sound/music. My contribution is pretty small, but it was a great thing to get involved with and a way of me connecting to ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2c013fff295afb4677cf","type":"link","fields":{"url":"https://tom.so/posts/wee-tour-of-p%C5%8Dneke/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"where I now call home","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":".","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"More details about each track and artist can be found on ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2c013fff295afb4677d0","type":"link","fields":{"url":"https://orllewin.github.io/elmet_brae/EB01/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"the dedicated microsite","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" set up by ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2c013fff295afb4677d1","type":"link","fields":{"url":"https://orllewin.github.io/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Gogledd Orllewin","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":". Album art was created by the talented ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2c013fff295afb4677d2","type":"link","fields":{"url":"https://nchrs.xyz/","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Rostiger","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":".","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Note: if you do end up liking this, please download it once and listen locally. ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2c013fff295afb4677d3","type":"link","fields":{"url":"https://archive.is/7DuT5","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Music streaming is not sustainable","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", and it is always better to have your own copy :)","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Elmet Brae', NULL, 'Some of us from Merveilles recently released a compilation of music inspired by the idea of the land.', '2023-12-06T11:00:00.000Z', 0, 'elmet-brae', '2025-10-24T07:34:48.554Z', '2025-10-24T07:33:27.378Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (16, 'Something for November', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The past few months have been great. Things have been moving at a slower pace, allowing me to be more reflective about my actions. Stressors that once existed in Auckland no longer apply - I can take my time, avoid rushing, and still have energy left at the end of the day. Now, I have the opportunity to think about the kind of person I want to be.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"When I left university, I felt desperate to do something meaningful with my life. I had spent four years at art school developing a practice, only to realise it wasn''t what I wanted. I needed something to identify with. My idea of a meaningful life was outward-facing, where I sought something to help those around me. Teaching seemed like a logical choice, especially after gaining some experience while in university under my mentor''s guidance.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Teaching went well for a while. I felt that my life had real purpose and a defined practice. I had these young people to help, and we worked together to achieve their goals. It was incredibly rewarding because we celebrated every success, no matter how big or small.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It is only since leaving teaching that I''ve realised a meaningful life should always start with the individual. Teaching was good to me, but it was a mistake to place so much personal value and worth into what is ultimately just a job. I had a glimpse of this when I first met my wife, but it has become clearer in recent months. What matters most are the people who mean a lot to me, my family, my friends, my ancestry - these are significant aspects contributing to a meaningful life. They are what will last even after everything and everyone else has left.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I might have mentioned this in a previous blog post, but that same mentor once told me, \"You come into this world with nothing, and after no time at all, you leave it with nothing but the connections you made along the way.\" To me, it emphasises the importance of finding your people and how temporary everything else is. In the end, none of that other stuff really matters.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''m not exactly sure why I decided to write a post like this. If I look at the analytics for this site, there are still a decent number of people who visit and go through different pages (300-400 visitors a week), so I assume that some of those people would also be reading these posts. But I can imagine someone like my past self from a few years ago, struggling through life, trying everything to find some meaning and purpose. If I could speak to that past version of myself now, I would tell them to stop getting stuck on things that don''t matter. Instead, I would suggest looking to family and friends, but also to their birthplace (Japan, in my case), and learn more about its culture and mythology.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I would tell myself, \"Stop treating your life as an island - you will feel much better for it.\"","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Something for November', NULL, 'The past few months have been great. Things have been moving at a slower pace, allowing me to be more reflective about my actions.', '2023-11-08T11:00:00.000Z', 0, 'something-for-november', '2025-10-24T07:36:23.695Z', '2025-10-24T07:35:14.784Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (17, 'Wee tour of Pōneke', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"68fb2cd53fff295afb4677d4","media":9,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Myself and a few others who are new to our company were given a tour of some significant sites around Wellington/Pōneke recently.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I had just arrived back from catching up with family, friends and students in Auckland, so was feeling quite run down prior to the trip. I knew that we would be out walking most of the day, so was a bit apprehensive about going.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Before we left, we were given a brief lecture on the history of Wellington and how it came into being. From the early arrival of Māori to the history of The New Zealand Land Company, it gave us much greater context around the establishment of the city we work in. Many of the streets I work near are named after the original directors of The New Zealand Land Company (such as Willis Street, Lambton Quay, and so on).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"68fb2cf23fff295afb4677d5","media":10,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"After the lecture we went on a bus tour around a few different sites. We visited the Cable Car Museum, Space Place, Karori Cemetery, and finally Ōtari-Wilton''s Bush. The latter was probably my favourite place, where we were given a tour of their plant nursery which housed rare species of native orchids and celmisia. It was incredible see that such a beautiful sanctuary for native flora and fauna exists so close to the city.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"68fb2d083fff295afb4677d6","media":11,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"All in all I was really thankful for the opportunity, and was glad to have gone on the trip.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Wee tour of Pōneke', NULL, 'Myself and a few others who are new to our company were given a tour of some significant sites around Wellington/Pōneke recently.', '2023-10-27T11:00:00.000Z', 0, 'wee-tour-of-pneke', '2025-10-24T07:39:39.992Z', '2025-10-24T07:36:39.833Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (18, 'A new chapter', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Note:","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" Surnames have been left out to maintain the privacy of the individuals mentioned below","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Several months ago now, I taught my last class and resigned from teaching after having done it for the past three years.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It really wasn''t an easy decision to make. I was leaving part-way through the year, right when I had establised a rapport with a new set of students and built even stronger connections with existing students. The ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb2d8f3fff295afb4677d7","type":"link","fields":{"url":"https://tewahi.com","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Te Wāhi maker space","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" that I was involved in was doing well, with many coming to the weekly Innovation Workshop I co-hosted. My confidence in the classroom was at its highest, having finally found my stride and style that I enjoyed using to help students with their work.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"So, why leave?","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"There were a few key reasons. The main reason being my wife getting a collections/archives related job in Wellington, one that she has always dreamed of. There wasn''t an equivalent in Auckland, so we would have to relocate no matter what. The logical thing for me would have been to find another teaching role here in Wellington - after all, there is a national shortage of teachers even now and (provided you are capable) one can pick up a full-time or relief role relatively easily. I would start again at another school, and that would be that.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"But I realised this wasn''t possible for me. I had given so much to my previous school because I believed in its staff and students very deeply, and felt truly invested in what was going on. Many of these students, some of whom I had been teaching since they were 14 years old, were now growing into young adults realising their dreams. In the three years I have been teaching, I have worked with close to 1000 different kids (likely a bit over if I counted up). I knew I couldn''t come close to that level of energy at a new school (or, it would take a very long time).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"With moving to a new place, I thought - why not have a completely fresh start? Try something different, and begin picking back up the things that I had to shelf for the past few years that I have been teaching. I had neglected many parts of my own life, namely my friends and family, in constant pursuit of this job which wasn''t healthy. Doing something more black and white could help me leave work at the door when I come home everyday.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am in a completely new job and field now (IT related), but I still think being a teacher in the classroom is one of the most rewarding things ever. It is a shame that the state of education and teaching in this country is as dire as is it, because on the job you have inclinations of what it could truly be. No other profession has made me laugh, shout and cry as much as teaching. It really gives you a sense of what is meant by the human condition (as cliche as that sounds), and just how much education can help shift social class barriers.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I will miss the team that I worked with dearly - Robin, Francis, Andre, Linda, Sandra, Tina, Sam and Motu. They are some of the most hardworking, funny, and talented people I have ever met. Others such as Shar, Joe and Jill were instrumental in me finding my feet when I first started teaching, to whom I am forever grateful.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Most of all, I will miss all of the students that I have been lucky enough to work with over the years - Bo, Isobel, Scarlett, Matthew, Eleanor, Stanley, George, Hidetomo, Taiji, Anne-Marie, Gabriella, Isaac, Violet, Lucas, Oscar, Sofie, Nathan, Sam, Aliza, Zara, Reese, Ruby, Amber, Sylvia, Christina, Hamish, Freddie, Olivia, Finn, Molly, Andrei, Seungjin, Ben, Aedan, Will, Noah, Callum, Jude et al. Thank you.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"id":"68fb2d8f3fff295afb4677d8","type":"link","fields":{"url":"https://www.are.na/block/23104563","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Bending towards the sun","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"T.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'A new chapter', NULL, 'Several months ago now, I taught my last class and resigned from teaching after having done it for the past three years.', '2023-09-22T12:00:00.000Z', 0, 'a-new-chapter', '2025-10-24T07:41:36.376Z', '2025-10-24T07:40:22.120Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (19, 'Tell them I said no', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"690319205eb6b167b541f6b8","style":"info","content":{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This is a bit of a whinge post sorry","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}},"blockName":"","blockType":"banner"},"format":"","version":2},{"type":"block","fields":{"id":"6900933300f0998219e0d492","media":17,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am currently reading the book “Tell Them I Said No” by Martin Herbert, which is a collection of essays regarding different artists who have deliberately withdrawn from the art world (or, as I liked to think of it as ”the supermarket”). ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I’m only a fraction of the way through it but it is a beautiful read. I really wish that my younger self could have come across this book while still at art school and trying to reckon with “playing the game”, at least in New Zealand. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This book came out in late 2016. At that time, I was still working and making collaboratively, and had a made few “successful” works that both pissed a lot of people off as well as registered commercial interest. We didn’t really know what we were doing, but I think there was a lot of naivety and arrogance on our part thinking that this balance of making engaging work and making money was “easy”.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"We got really far, but ultimately I found out the hard way that this world wasn’t really for me and I turned away from it completely. Since then I have made a few small things here and there, but have largely turned my back on making from the hurt that I experienced when I was younger. I said yes to a lot of things which I probably should’ve said no, but I suppose that is the benefit of hindsight.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Things might have turned out a bit differently if I had read this book in 2016. I could have learned about how someone like David Hammons had dealt with similar issues - that you can step back from all the nonsense but continue to engage in a critical and meaningful way without selling yourself away. You don’t have to give up on making completely, and if anything poke fun at the enormous power imbalance that exists in the industry (and probably always will).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6900971c36105819bbe45c4b","media":18,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"At this point I don’t know if I will ever engage in the art world ever again, or even try to make “art” in the same way. I’ll probably always be working on small things, but never for the purpose of a gallery circuit or something similar. I used to feel quite cut about this but I think I’ve found other things to occupy myself. The art world and its creatures helped me learn about different things that have shaped how I conduct myself in a broader sense which has probably been the most productive thing. If anything, it actually taught me very little about art making lol.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Tell them I said no', NULL, 'A book I should have read years ago. ', '2025-10-28T09:00:00.000Z', 0, 'tell-them-i-said-no', '2025-10-30T07:52:38.572Z', '2025-10-28T09:55:08.009Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (20, 'In praise of tinkering', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''ve been using Linux distributions as my primary operating system since I was a teenager in highschool. I''d saved $450 of my hard earned pocket money, and bought a second-hand Sony Vaio Core 2 Duo machine from NZ Daisuki (better known as \"Japanese Trade Me\" in my family). ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6919a7a03296eba8dbdb9559","media":20,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I was so excited. Finally my own computer, I can download and run whatever software I want! It came with Windows 7 preinstalled, so I preceded to customise it with all kinds of third party skins and themes from Zedge and pasted all kinds of registry hacks from YouTube tutorials to try get the most out of this machine. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It was fun for a while, but it wasn''t long before Microsoft started to complain. I was technically running an outdated version of Windows 7, but each successive update made my machine incredibly slow, and it appeared that the future of Windows was that of Metro UI - flat, touch friendly interface with very little customisation available. I didn''t want to lose this awesome and crazy hacked OS, but having an outdated, unsupported system was also starting to worry me. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6919a6c33296eba8dbdb9558","media":19,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Then by pure chance, I happened upon a desktop image on Tumblr of a Ubuntu system running i3 window manager with a Touhou background. It was about as weeb as you could get, but I loved how personalised it was and immediately wanted to find out more. What was a window manager? Xorg? i3-gaps? I was fascinated by this new rabbit hole I''d opened up. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The rest is probably quite similar to how a lot of people like to personalise their Linux machines. I knew nothing when it came to using a package manager, using a terminal etc and it was obviously far before LLMs, so I spent countless hours on Stackoverflow and the Arch Linux wiki trying to tinker. It was so frustrating, with several of my endeavours leading to kernel panics and completely messed up boot loaders, but boy did I have fun. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Little did I know that my pursuit in making the \"ultimate Linux system\" resulted in me learning about how Linux and Unix-like systems work, basic shell scripting, and networking. Soon enough I was also tinkering on hobby VPS boxes, learning about LAMP, hosting small Wordpress and Discourse instances for my friends, and feeling increasingly like the world was my oyster with respect to computers. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It was all thanks to that old Sony Vaio laptop, which still works to this day (although now runs Slackware) and the fact that I had such a dogshit experience with Microsoft that I started tinkering with computers. I credit it in part with me ending up as a software developer much later on in life and for fuelling my creativity where all other avenues ran dry. Messing around with alternative operating systems like Linux (and some BSDs) made my experience with these machines felt so real. If I entered a bad command or mucked up some kind of Nginx rule, it would be my fault and that was awesome. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The weird thing is that I miss administering Linux boxes that could completely shit the bed if I misconfigured something. These are all \"bad\" things but they felt REAL. I felt like I was in a feedback loop with my machine. I knew when I made a mistake, and could immediately learn as to what I''d done wrong. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"What seemed like endless troubleshooting of my own fuck ups was in fact a series of invaluable lessons on debugging and learning to be a good developer. In most other pursuits like art or sports I would grow frustrated and impatient, but for whatever reason the computer just never stopped being interesting. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It is probably the case for most things in life now, but I do wish failure was more socially acceptable. I failed countless times over the years using Linux, but I''ve learned so much as a result. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"That''s the real point, I think. I''m incredibly grateful for the mess and freedom I had to tinker. I was looking for a way to have a \"computer that could do cool shit\", one that I could show off to my friends in high school, and ended up with a career in making computers do cool shit lol. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'In praise of tinkering', NULL, 'A wee love letter to Linux', '2025-11-16T09:00:00.000Z', 0, 'in-praise-of-tinkering', '2025-11-16T10:31:24.878Z', '2025-11-16T10:22:31.633Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (21, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2025-11-24T10:24:36.155Z', '2025-11-24T10:24:36.153Z', 'draft');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (22, 'Stainless is amazing', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Recently I created a hobby API service called ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927bfd25c552e06dcdd5b3f","type":"link","fields":{"url":"https://schools.tom.so","linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"schools.tom.so","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":". It is running on a relatively simple stack of Cloudflare Workers, Drizzle, Hono, OpenAPI and SQLite. In a nutshell, it \"ingests\" the ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c1ce5c552e06dcdd5b48","type":"link","fields":{"url":"https://www.educationcounts.govt.nz/directories/school-directory-api","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"schools directory dataset from the Ministry of Education","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" as a scheduled task and (re)serves this as a REST API.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Technically it is possible and perfectly fine to use the endpoints from data.govt.nz directly, but from past experience I''ve found that the performance can dramatically slow down or go offline completely. Also, the way they recommend acting with their API is kind of crazy:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6927c3f441837d2e199b65b6","media":23,"blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Yes sir, that is a raw dog SQL query being made in the URL param lol. I get that being able to do SQL joins between tables in their datastore via HTTP would be useful, especially since this is an open data government portal aimed at researchers would be used to a CKAN API/SQL... but who knows 🤷","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"In any case, acting as a mirror on Cloudflare means that you immediately get all of the edge speed benefits out of the box with Workers, and using their KV store product also means that you can cache the responses as well (since it isn''t like new schools are coming online in New Zealand frequently). So, I opted to create this and have an OpenAPI spec generator running as well (comes out of the box with Hono).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This was all working nicely and without issue, but then I stumbled upon ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c0285c552e06dcdd5b40","type":"link","fields":{"url":"https://stainless.com","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Stainless","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", an SDK generation service similar to Speakeasy that also offered MCP server support. I saw that the ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c0795c552e06dcdd5b42","type":"link","fields":{"url":"https://github.com/sst/opencode-sdk-python","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"SST team","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" and ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c0555c552e06dcdd5b41","type":"link","fields":{"url":"https://www.terminal.shop/api#client-sdks","linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"terminal.shop","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" were already using this for their multi-language SDKs, so I tried pointing it to my API service.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"As a complete normie and noob when it comes to building out your own SDK, let alone an MCP server, this was genuinely such a painless and smooth experience. So far I haven''t actually needed to pay anything, and have SDKs for ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c0955c552e06dcdd5b43","type":"link","fields":{"url":"https://github.com/et0and/schools-sdk-typescript","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Typescript","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c0b65c552e06dcdd5b45","type":"link","fields":{"url":"https://github.com/et0and/schools-sdk-php","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"PHP","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c0a65c552e06dcdd5b44","type":"link","fields":{"url":"https://github.com/et0and/schools-sdk-python","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Python","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", and ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c0d35c552e06dcdd5b46","type":"link","fields":{"url":"https://www.npmjs.com/package/schools-sdk-mcp","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"the MCP server","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" all running for free. The Stainless bot automatically creates PRs and releases in the respective repositories, but ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"I haven''t had to set any of this up myself","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":".","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The fact that this service is basically completely hands-off and language agnostic is huge in my opinion. I don''t know what the pricing is, but whatever it is I think it is fully worth it lol. Take a look at me asking my schools MCP to give me some facts about Takapuna Grammar School (my old place of work):","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6927be197230e15de599443c","media":21,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"You can see it immediately recognises the tools that the MCP offers. I did not write any of these tools myself - Stainless has defined these based on my OpenAPI spec which outlines each endpoint and what it returns.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"After a short while, it returns the basic facts that I asked for:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6927bea87230e15de599443d","media":22,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This entire project took maybe a day to set up and get running, including all of the Cloudflare Workers deployment and the Stainless configuration. While the capabilities are still very simple, I think this could enable some really interesting and powerful workflows through the combination of data sources. For example, I could have my API service consume multiple datasets related to education, not just from data.govt.nz but from other sources, and then have an agent or LLM access one or more tools based on my natural language query to join and serve responses.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"If you want to give it a go, feel free to ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6927c1125c552e06dcdd5b47","type":"link","fields":{"url":"https://github.com/et0and/schools-sdk-typescript/tree/main/packages/mcp-server","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"follow the steps outlined in my MCP package doc","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":". You should be able to add and interact with this using any modern editor or agent so long as you have Node installed. Despite it saying you need an API key this is not required at least at the moment, although it might change in the future if I start needing to serve more data sources (or things start getting costly). Otherwise, maybe try making your own!","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Stainless is amazing', NULL, 'How I built a toy MCP server with Stainless', '2025-11-27T03:00:00.000Z', 0, 'stainless-is-amazing', '2025-11-27T03:26:29.587Z', '2025-11-27T02:41:16.042Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (23, 'Writing with AI is a cop out', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"By now it’s pretty much everywhere, but I’ve started to get a very good eye for spotting when some piece of content has been written by AI. It doesn’t matter what the model is, if it’s the new SOTA of OpenAI/Anthropic/Google/Meta or whatever. They all sound like shit and it’s obvious. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"Case in point, there is a very large number of “people” on Twitter/X who have LLM replies. In some cases these will be bots, but I actually suspect that there’s a high number of people that literally defer their thoughts and opinions to some AI browser plugin. I started seeing it mostly across tech accounts, but you tend to see it everywhere now. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"693d33daa7bbb89525abc79e","media":25,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"What do you gain from outsourcing your literal ability to think to an LLM? Writing is inherently messy and difficult if you are trying to express some idea, but that’s precisely the point. It is meant to be hard because it forces you to think and validate your thoughts in a way that others, including yourself, can structure and comprehend in some shape, way or form. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"If you prompt an LLM that in itself is a form of writing that requires thought and consideration. You need to structure your thought in such a way that it can be comprehended by the LLM, which would likely also mean it is understandable to other humans too. But in the case of that reply to Dax’s post above I’m convinced the user didn’t even prompt the LLM. At most of they might’ve said something like “write a response to this tweet”. What the fuck is the point?","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"I’ve seen more examples at work too where commit messages are AI, PR titles and descriptions are AI, the code itself is AI, and any comments in said code is also AI. At most you’ve probably prompted the code itself, but everything else you’ve click opsed within VS Code and GitHub with their AI generation features. There’s then a very high chance of it basically being complete slop all the way down. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"The transformer architecture of an LLM inherently makes it such that you can never be “creative” by it alone. An AI bot is empty insofar as it just produces a pattern of some kind, but this in isolation isn’t that malicious. No, what’s more insidious is when there are still living and breathing humans that simply hit “publish” without any other engagement. This is worse than dead internet theory. How does that make you any different from said machine then? Doing this means you’ve given up and surrendered your ability to engage with the world in a meaningful way.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"I’ve become so conditioned by encountering these things that I second guess myself now when I write. I genuinely will edit something I’ve written because I think it “sounds too AI”, and avoid the use of emdashes and hyphens for the same reason. If a paragraph is around 3 sentences long (this is how I was taught in university), I think the structure “looks like AI” as I’ve observed LLMs have a tendency of sticking with shorter paragraphs rather than long ones. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"Aristotle refers to a term called “lógos” which roughly translates to word, discourse or reason. That is, the written word means one’s ability to formulate their own thinking, understanding and order. This is all very philosophical, but it is also deeply rooted in human psychology insofar as our ability to write is a ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"693d3391a7bbb89525abc79d","type":"link","fields":{"url":"https://summit.sfu.ca/item/2296","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"primary driver of our cognitive development","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" (particularly in children). This makes our ability to write something deeply human and very real. It isn’t just language that instills and gives form to true intelligence but our means of shaping it via the written word. Give this up and we are potentially throwing away a core tenet of what makes us human…","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"LLMs are cool sure. I’ve used them a lot particularly this past year to brainstorm, debug and learn as a developer. But I would never want to voluntarily make myself an empty mouthpiece for an LLM. Doing so is the equivalent of unplugging my brain completely for some memetic machine that is far, far from actual intelligence. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Writing with AI is a cop out', NULL, 'It sounds like shit and it’s obvious', '2025-12-13T09:00:00.000Z', 0, 'writing-with-ai-is-a-cop-out', '2025-12-13T10:08:55.606Z', '2025-12-13T09:34:52.493Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (24, 'People deserve better', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Over the Christmas and New Year period here in New Zealand, one of the largest and widely used healthcare portals used by doctors and health centres ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"695c545acaf42b7e1bbbd723","type":"link","fields":{"url":"https://www.rnz.co.nz/news/national/583248/manage-my-health-data-breach-ransom-deadline-arrives","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"got hacked","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":". 108GiB worth of personal health data, including (in some cases) passport scans, prescription information, names, addresses, NHI numbers etc from this Manage My Health (MMH). Initially the group responsible (Kazu) asked for a 300K ransom, but then lowered this to 60K in an effort to try and force MMH''s hand.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"695c54b2caf42b7e1bbbd724","media":26,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"MMH has basically been completely silent since the hack was made public. Most health practices found out about the breach via media outlets, and only after repeated attempts to contact MMH failed so Kazu then posted a sample of the hacked data. It is unclear how the breach happened, if the exploit has since been fixed, who exactly has been affected and how long the vulnerability has existed in the MMH portal.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"While the government is chasing it''s tail launching all sorts of different reviews and injunctions, much of this in my opinion is focusing on the wrong questions. It is unacceptable for a ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"HEALTHCARE","type":"text","style":"","detail":0,"format":2,"version":1},{"mode":"normal","text":" SaaS platform to not have SOC 2 compliance and basic opsec at a minimum. They should be as secure as financial services like banks, if not more secure. Given how many health centres use MMH as a way for patients to manage prescription repeats, bookings etc, it is unfair for normal everyday people who have been pushed to use this shitty platform only to have their data mishandled.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Their ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"695c5780caf42b7e1bbbd725","type":"link","fields":{"url":"https://archive.is/6VGLs","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"security page is incredibly vague","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" and just talks about SSL certificates. It doesn''t specify anything like where the data is stored, how it is stored (encrypted at rest, in transit, etc), if MMH undertake security audits, and instead just talks about how they have certs from GoDaddy (lol) and for the user to use antivirus on their computer. This should have been a massive red flag to anyone with a modicum of computer security knowledge looking to procure their services.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"The fact that MMH somehow became the preferred healthcare portal in New Zealand is insane to me. They haven''t apologised about the breach and instead are putting out the weakest damage control. This is clearly a massive fuck up on their part. From ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"695c5a9acaf42b7e1bbbd726","type":"link","fields":{"url":"https://www.linkedin.com/feed/update/urn:li:activity:7413120799634743296/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"a recent LinkedIn post they state","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":":","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"\"The investigation has identified that one module, Health Documents, within the app was compromised, not the entire app. Manage My Health is commencing legal action to protect client data.\"","type":"text","style":"","detail":0,"format":2,"version":1}],"direction":null,"textStyle":"","textFormat":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Based on what I''ve read and inferred, this \"module\" was essentially a fuck up with how they set up Azure Blob storage where all documents and attachments were stored. I''m not going to post the exact source here, but some searches on Twitter will bring up posts that show this may well be the case. So this has likely been public for a very long time before Kazu even came across it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I also found the following point from MMH very rich:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"\"Manage My Health has [...] Re-secured all health documents and strengthened document storage controls.\"","type":"text","style":"","detail":0,"format":2,"version":1}],"direction":null,"textStyle":"","textFormat":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Bro, you cannot \"re-secure\" documents that were publicly accessible. They were not \"secure\" in the first place, so at most you are fixing access to the blob storage/bucket but the files themselves are wide open and fucked now. Also, nagging your users on making sure they have secure passwords and 2FA is meaningless if you can''t secure your own infra. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This is shaping up to be one of the worst cybersecurity breaches in New Zealand and so far it appears that no one will be having to face the music. It is a failure on MMH''s part, but it is a wider signal showing the poor state of the system itself and its shitty standards. ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"695c5b6dcaf42b7e1bbbd727","type":"link","fields":{"url":"https://www.openaccess.nz/blog/managemyhealth-hack-a-failure-of-standards/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Callum McMenamin has written an excellent account of this","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" that goes over this in great detail. Self-attestation is a massive issue with vendors - we need a legal standard that companies need to follow to ensure the secure handling of user data, and if not then appropriate fines and/or jail.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'People deserve better', NULL, 'Some thoughts on the recent Manage My Health hack', '2026-01-05T22:30:00.000Z', 0, 'people-deserve-better', '2026-01-06T01:02:08.808Z', '2026-01-06T00:12:09.564Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (25, 'Using agents in Opencode', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"For the past six months I''ve been using ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69642d20939c257c033c3d88","type":"link","fields":{"url":"https://opencode.ai","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Opencode","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" very heavily for my own personal projects. It is an \"agentic\" CLI tool similar to Claude Code, Amp and Codex, but is (in my opinion) far more powerful and polished than every other TUI tool currently available. While most CLI tools use ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69642db9939c257c033c3d8b","type":"link","fields":{"url":"https://github.com/charmbracelet/bubbletea","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Bubbletea","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" or ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69642dcc939c257c033c3d8c","type":"link","fields":{"url":"https://github.com/vadimdemedes/ink","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"React Ink","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", Opencode has created its own TUI library in Zig called ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69642da7939c257c033c3d8a","type":"link","fields":{"url":"https://github.com/anomalyco/opentui","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Opentui","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" and it is genuinely incredible what it is capable of in terms of performance and rendering.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Like many other tools, Opencode has the ability to ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69642d4f939c257c033c3d89","type":"link","fields":{"url":"https://opencode.ai/docs/agents/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"define custom agents, subagents and commands","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" with just markdown files. These are essentially prompt files, but with some config like being able to set the temperature of the response or a specific model for certain tasks (e.g. a model with a large context window like Gemini would be better used for mapping a codebase, while Opus or Sonnet would be better at planning or building a feature). Opencode comes with some default agents and subagents, like a planning agent that does not have write or edit tool ability, but is instead useful for e.g. conversing with a codebase.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I got the idea to try creating subagents that run in parallel recently when browsing ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69642e5e939c257c033c3d8d","type":"link","fields":{"url":"https://github.com/elithrar/dotfiles","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Matt Silverlock''s dotfiles on GitHub","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":". Here, he had his agent and command files for Opencode which specialised in parallel review subagents that are triggered by a ","type":"text","style":"","detail":0,"format":0,"version":1},{"mode":"normal","text":"/review","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":" command:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"\"Review the code changes using THREE (3) @code-review subagents and correlate results into a summary ranked by severity. Use the provided user guidance to steer the review and focus on specific code paths, changes, and/or areas of concern.\"","type":"text","style":"","detail":0,"format":2,"version":1}],"direction":null,"textStyle":"","textFormat":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I loved the look of this, so I promptly copied this command and the associated subagent file to try it out. Using an open weight model like GLM 4.7, I was able to get very good feedback on some changes I was about to commit and that CodeRabbit and Copilot had missed. I imagine if I was to use Opus as my primary model for this the results would be even better. Basically, each subagent was focusing on something different, and then generated a collated summary at the end that I could go through and work through:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"69643036939c257c033c3d8e","media":27,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This combined approach feels to me like a good compromise between a standard, single prompt input, and the hugely expensive ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"696430ec58fa22ce54c212d6","type":"link","fields":{"url":"https://venturebeat.com/technology/how-ralph-wiggum-went-from-the-simpsons-to-the-biggest-name-in-ai-right-now","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Ralph Wiggum approach","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" that seems to be all the rage on Twitter at the moment. Potentially, if you are trying to think of different approaches to solving a problem this technique could produce something novel (or at least something you might not have thought of initially).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am trying to take all of this stuff with a grain of salt still since LLMs can still make catastrophic mistakes (and doesn''t really understand what it is doing), but tools like this can definitely help to flatten the feedback loop.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Using agents in Opencode', NULL, 'Experimenting with parallel (sub)agents for rapid reviews', '2026-01-11T22:00:00.000Z', 0, 'using-agents-in-opencode', '2026-01-11T23:46:02.704Z', '2026-01-11T23:00:01.755Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (26, 'I still feel like an imposter', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"696ed00799adc8b038ad9101","style":"info","content":{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This is another whinge post, sorry","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}},"blockName":"","blockType":"banner"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''ve been professionally working as a software engineer now for 11 months. When I started I very much felt like an imposter, but that was somewhat to be expected given that I didn''t come from a traditional computer science or technology background, so figured the feeling would begin to go away after a few months of learning and general work experience. I thought so long as I stay on top of things it would begin to feel a bit easier/natural for me.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Truth is, that really hasn''t been the case. If anything it has gotten harder. I can''t even really Dunning-Kruger myself, because as soon as I feel like I am getting the hang of something I get hit in the face with shit lol. Every day I feel like I begin unravelling something as part of my job or personal projects, and in doing so I uncover 5+ things that I know absolutely nothing about and don''t even know where to start.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"When I was a teacher, it was a similar feeling in the beginning but the good ol'' \"fake it ''til you make it\" mantra actually applied here. I got to a point after roughly a year where I didn''t need to fake it anymore and I had confidence in the classroom. But with SWE, I feel like this mantra just doesn''t work and if anything will continually bite you in the arse. AI/LLMs make it seem like it''s so easy to pick things up quickly, as though you are inserting those knowledge cartridge things like Neo in the Matrix, but by the time you have finished verifying its bullshit it''s probably taken three times as long as reading a book or something, and your mental load is fucked. You have to be continually asking questions, big and small, in order to be fully confident that you understand something, but in a work environment I don''t believe this isn''t necessarily possible.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Despite all this time and the best LLMs at my disposable, the reality is that I still feel like a fraud and an imposter. I still suck as DSA, my system design knowledge is limited at best, and I just really struggle to be confident in my work. I''m second guessing everything that I write/make, like there''s nowhere to hide, no magic or mystery, and I just feel embarrassed. It is really hard to keep pushing myself whilst being in this mindset. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''m curious to know if there are others who feel a similar way. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'I still feel like an imposter', NULL, 'The more I learn, the uncertainty seems to follow', '2026-01-19T23:30:00.000Z', 0, 'i-still-feel-like-an-imposter', '2026-01-20T00:50:41.746Z', '2026-01-20T00:25:55.554Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (27, 'Clawdbot is kind of insane', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"In my Twitter/X echo chamber over the weekend, I''ve been witnessing some of the craziest stuff being posted by tech/dev accounts with regards to ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b34c53858267e3d17d85","type":"link","fields":{"url":"https://clawd.bot/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Clawdbot","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", which I like to think of as being like ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b33953858267e3d17d84","type":"link","fields":{"url":"https://claude.com/blog/cowork-research-preview","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Claude Cowork","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" but for your entire life and very much targeted at developers.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"For context, Clawdbot runs on your machine like a Linux VPS and opens a gateway via Whatsapp, Discord, Telegram et al that you can chat via. It has skills and plugins similar to Claude Code, only you are essentially giving it complete unfettered access to your machine, logins (if you enable this), web searches (via the Brave Search API), and so on. Most people are running this using hosted models like Claude, GPT, Gemini etc, but technically it can support local models via Ollama.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Now this seems pretty cool in theory, as you are creating your own virtual assistant like Siri that is far more capable with access to real tools, but digging deeper there were a couple of weird things that I noticed.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6976b83da5a2f705d3ab4b33","media":29,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People buying Mac Minis for the sole purpose of running Clawdbot","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". These machines (at least in New Zealand) are over $1,000 for the base model. While Clawdbot is somewhat resource intensive on paper, most people have gotten cheap VPSs or disused laptops running fine. The only differentiator would be the ability to use iMessage as a bridge on a native macOS machine, but this seems extreme given that the manner in which you interface with Clawdbot (chat, or sometimes voice) is basically the same across all providers. Even the author of Clawdbot pointed out ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b3be53858267e3d17d86","type":"link","fields":{"url":"https://x.com/clawdbot/status/2015265005210353824?s=46","linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"this is kind of stupid","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" lol.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":1},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People not securing their ports","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". Clawdbot uses port 18789 by default for its gateway. Luic Catacora from Replicate pointed out that ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b3e053858267e3d17d87","type":"link","fields":{"url":"https://x.com/lucatac0/status/2015473205863948714","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"many people have insecure config for their Clawdbot setups","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", meaning that gateways are completely exposed publicly on services like Shodan:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6976b23853858267e3d17d82","media":28,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People will have API keys stored here for Google Workspace, Anthropic, OpenAI, full shell access and browser automation. A recipe to get pwned and have a very, very bad day.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People sharing personal data with AI labs","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". I mean most people already do this and get ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b32253858267e3d17d83","type":"link","fields":{"url":"https://en.wikipedia.org/wiki/Chatbot_psychosis","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"oneshotted via a ChatGPT psychosis","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", but willingly giving access to your browser and emails seems like the next step surely lol. I wouldn''t really want all of my emailed invoices etc as part of Sam Altman''s next training data batch, but maybe others have resigned to that fact. Having them train off your company code is one thing, but then giving it access to the rest of your life is a bit much...","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I don''t want to give off the impression that I hate the project or anything. I think it''s a cool example of FOSS software going the extra mile in competing with proprietary alternatives (in this case Cowork), and the fact that ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b47e53858267e3d17d88","type":"link","fields":{"url":"https://steipete.me/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Peter Steinberger","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" (the author) open-sourced it is awesome. This is a very powerful tool, and it isn''t necessarily the fault of the tool if people decide to be a bit silly with it (the same would apply to Cowork). But, I do think it reflects on how powerful the current AI/LLM hype cycle is, such that even the most experienced developers will decide to YOLO their security to run a potentially unsecured LLM and webserver on their machine.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null,"textFormat":1}}', 'Clawdbot is kind of insane', NULL, 'It''s a friendly looking crustacean, but careful! It might bite you in the arse', '2026-01-25T23:30:00.000Z', 0, 'clawdbot-is-kind-of-insane', '2026-01-26T00:43:19.140Z', '2026-01-26T00:03:57.197Z', 'published');
INSERT INTO "posts" ("id", "title", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (28, 'AI is making me anxious and stupid', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"I’ve been at a bit of a loss since the start of this year. Since Opus 4.5, LLMs including open weight models such as Kimi 2.5 and GLM 4.7 have (in my opinion) gotten incredibly good. While each release and improvement now is only incremental, the tooling and ecosystem around models is ever changing. The moat now isn’t who has the best model since they are all really good, but the tooling that you build around it (e.g. proprietary à la Claude Code or something FOSS like OpenCode). ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"Keeping up with these developments is exhausting even if you’re  terminally online. Apparently ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6988778b620d2808bc0f4ac4","type":"link","fields":{"url":"https://x.com/zeeg/status/2012604638759915579?s=46","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"MCPs are so last year and skills are the new thing","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":"? If you don’t have an AGENTS.md, cursor rules file, parallel subagents running in sandboxed Hetzner VPS instances using multiple models in a Ralph Wiggum loop with git worktrees that is split across different domains you’re not gonna make it bro /s. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6988785d620d2808bc0f4ac5","media":33,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"In all seriousness, I’ve been trying my best to keep up and give it a proper shot whilst still trying to “git gud” at things that traditionally make a solid engineer. People online will often talk about how important it is to have a solid understanding of the fundamentals so that you can drive LLMs correctly, and you don’t become overly reliant on them for everything that you build. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"But using AI feels genuinely addictive. It has become too easy to prompt an agent even for the easiest tasks because it is technically easier (although this is 50/50, since models still can fuck up in hilarious ways and end up taking twice as long). With an overly confident Claude or Codex, you feel as though you can learn anything and pick anything up instantly, and you begin to think that this must be true because that’s what all the cool kids on Twitter are saying. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"The problem is AI hasn’t always accelerated my work or learning. If anything, sometimes I unfortunately find myself trusting its take more than my own gut. Surely Anthropic and OpenAI with ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69887408f08521b4bd8c6ba8","type":"link","fields":{"url":"https://www.reuters.com/technology/anthropics-more-than-20-billion-funding-close-soon-next-week-bloomberg-news-2026-02-07/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"tens of billions of dollars in funding","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" and some of the best researchers in the world have engineered this model to be smarter than me. I doubt myself, I think I’m a dumbass without Claude, I feel useless without an LLM and I need it to function as a developer. But this isn’t at all true, and if anything I am deliberately making myself (or at the very least making myself feel) stupider than what I actually am because I don’t really have that solid foundational understanding to fall back on. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"69887496f08521b4bd8c6ba9","media":30,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"If anything, perhaps LLMs have highlighted the “Mr. Clumsy” nature in me. For context, Mr. Clumsy is a character from Roger Hargreaves excellent “Mr. Men” series of books, whose anxiety and nervousness is causing them to always doubt their own ability. Claude brings out the Mr. Clumsy in me as it accelerates my anxiety of “getting it right” the first time and not giving myself the chance to fail in a spectacular way. Mr. Clumsy gets frustrated at the feeling of being incapable of doing basic tasks, trusting your own ability to think, and that’s is maybe what AI has been doing to me. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"I think that I must not be the only Mr. Clumsy developer out there. The cycle is real, and I wouldn’t be surprised if others (particularly juniors to mid level like myself) felt the same way. On the one hand I’m comforted by people like ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69887379f08521b4bd8c6ba4","type":"link","fields":{"url":"https://x.com/gergelyorosz/status/2019123213364764837?s=46","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Grady Booch","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" who believe that similar events like this have happened before and AI won’t ever make us developers fully obsolete, but my ever growing dependence on these models is scaring the shit out of me because I am starting to doubt myself in terms of what I genuinely do know.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"69887512f08521b4bd8c6baa","media":31,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"As a person and developer, I probably need to be more like Mr. Silly from Nonsenseland. In his case, he relentlessly pursuits the “Nonsense Cup”, and is a champion at keeping on. He just keeps on going regardless, much as others probably should despite what AI lab talking head is saying on Twitter or what my own internal Mr. Clumsy is saying. It will likely piss some people off by seeming overconfident and I would like to avoid this where possible, but I don’t want to become totally beholden to the shiny matmul machine. I would hope at many chances of failing but ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69887379f08521b4bd8c6ba5","type":"link","fields":{"url":"https://en.wikipedia.org/wiki/The_Myth_of_Sisyphus","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"being able to smile","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" as I did than begin to doubt in myself. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"69887560f08521b4bd8c6bab","media":32,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'AI is making me anxious and stupid', NULL, 'Claude … you’re giving me trust issues', '2026-02-08T11:00:00.000Z', 0, 'ai-is-making-me-anxious-and-stupid', '2026-02-08T11:50:35.060Z', '2026-02-06T07:30:19.115Z', 'published');
INSERT INTO "works" ("id", "title", "summary", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (1, 'An idea for a performance', 'A tool for generating performance ideas.', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"692432866cd1ab265ae9da5c","arenaSlug":"an-idea-for-a-performance","blockType":"arena","arenaTitle":"An idea for a performance "},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"An idea for a performance is a web experiment and are.na channel that displays random ideas for performances, built using the are.na API.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'An idea for a performance', NULL, 'A tool for generating performance ideas.', '2025-10-22T11:00:00.000Z', 0, 'an-idea-for-a-performance', '2025-11-27T04:26:02.743Z', '2025-10-24T06:56:35.595Z', 'published');
