INSERT INTO "works" ("id", "title", "summary", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (3, 'Aotearoa artist ephemera', 'An archive of artist and gallery materials.', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"68fb28cf3fff295afb4677ca","media":7,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Aotearoa artist ephemera was an online archive of artist and gallery ephemera from Aotearoa New Zealand, dating from the early 1970s to the present day.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Most of these files are still under the respective copyright of the artist(s) and their representing galleries. As a result, this is simply an educational resource for the general public, but with the copyright held by their respective owners. I don''t own anything here. Besides use for personal research this material is not intended to be used for profit.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Aotearoa artist ephemera', NULL, 'An archive of artist and gallery materials.', '2025-10-22T11:00:00.000Z', 0, 'aotearoa-artist-ephemera', '2026-01-17T06:50:42.827Z', '2025-10-24T07:20:01.106Z', 'published');
