INSERT INTO "works" ("id", "title", "summary", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (6, 'WWW', 'A mass archive of weird, wonderful websites.', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"6927cfd5bb57886e2d019ae6","arenaSlug":"www-t_kopepmelw","blockName":"","blockType":"arena","arenaTitle":"WWW"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"id":"68fb307e3fff295afb4677f3","type":"link","fields":{"url":"https://www.are.na/tom-y/www-t_kopepmelw","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"WWW","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" is a collection of over 800 unique and interesting sites on the World Wide Web. It serves as both a record and point of reference whenever I embark on a new online project.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'WWW', NULL, 'A mass archive of weird, wonderful websites.', '2025-10-22T11:00:00.000Z', 0, 'www', '2025-11-27T04:23:35.966Z', '2025-10-24T07:52:23.650Z', 'published');
INSERT INTO "works" ("id", "title", "summary", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (7, 'Hyperjam', 'A Merveilles online game festival.', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"68fb324acfd6350854a26b87","media":15,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"id":"68fb31f4cfd6350854a26b85","type":"link","fields":{"url":"https://itch.io/jam/merveilles-hyperjam/entries","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Hyperjam","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" was an online interactive art event hosted by Merveilles. Within a virtualised HyperCard environment, all participants created interactive works over the first weekend of April.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"See also: ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb320bcfd6350854a26b86","type":"link","fields":{"url":"/work/museum-without-walls","linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"The Museum Without Walls","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Hyperjam', NULL, 'A Merveilles online game festival.', '2025-10-22T11:00:00.000Z', 0, 'hyperjam', '2025-10-24T08:02:20.068Z', '2025-10-24T07:58:55.453Z', 'published');
INSERT INTO "works" ("id", "title", "summary", "hero_image_id", "content", "meta_title", "meta_image_id", "meta_description", "published_at", "generate_slug", "slug", "updated_at", "created_at", "_status") VALUES (8, 'Museum without walls', 'A game made for Macintosh Plus.', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"68fb388962ec3aad445a3b34","media":16,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"id":"68fb32d4cfd6350854a26b88","type":"link","fields":{"url":"https://tomupom.itch.io/the-museum-without-walls","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"The museum without walls","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" was a project for the first ever ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb32d4cfd6350854a26b89","type":"link","fields":{"url":"https://tom-so.vercel.app/work/hyperjam","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Merveilles Hyperjam","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", created over a three day period within an emulated Macintosh Plus environment. While the sequencing is fairly basic, it was great fun to make work using Hypercard and watch what other people created.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"You will need to be running a ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb32d4cfd6350854a26b8a","type":"link","fields":{"url":"https://www.gryphel.com/c/minivmac/index.html","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Hypercard viewer or emulator","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" in order to play this game. Otherwise, ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb32d4cfd6350854a26b8b","type":"link","fields":{"url":"https://mww.tom.so","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"play in the browser","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":"(24MiB) and navigate to The Museum Without Walls.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Museum without walls', NULL, 'A game made for Macintosh Plus.', '2025-10-22T11:00:00.000Z', 0, 'museum-without-walls', '2025-10-24T08:28:12.109Z', '2025-10-24T08:03:17.982Z', 'published');
