INSERT INTO "_pages_v" ("id", "parent_id", "version_title", "version_hero_type", "version_hero_rich_text", "version_hero_media_id", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (2, 1, 'Home', 'highImpact', '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"tag":"h1","type":"heading","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Payload Website Template","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"type":"link","fields":{"url":"/admin","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Visit the admin dashboard","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"mode":"normal","text":" to begin managing this site''s content. The code for this template is completely open-source and can be found ","type":"text","style":"","detail":0,"format":0,"version":1},{"type":"link","fields":{"url":"https://github.com/payloadcms/payload/tree/main/templates/website","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"on our Github","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr"},{"mode":"normal","text":". ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":"ltr","textFormat":0}],"direction":"ltr"}}', NULL, 'Payload Website Template', NULL, 'An open-source website built with Payload and Next.js.', NULL, 0, 'home', '2025-10-24T05:19:55.690Z', '2025-10-24T05:19:55.688Z', 'published', '2025-10-24T05:19:56.139Z', '2025-10-24T05:19:56.139Z', 1, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (11, 5, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2025-10-24T06:44:24.365Z', '2025-10-24T06:44:24.364Z', 'draft', '2025-10-24T06:44:24.774Z', '2025-10-24T06:44:24.774Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (12, 5, 'North Virginia is for lovers (of cascading failures)', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"So chances are you have already read about this, but from about 9pm last night I began to experience issues with logging into a bunch of services online. Turns out it was the early signs of what would become a major outage with the us-east-1 AWS region that would take out a bunch of different popular services (including Strapi Cloud, which I use for this blog lol).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It''s made me reflect on AWS as a whole. I''ve been learning about different AWS products and microservice architectures in general over the past year, as this is our primary approach with the tools and services we write at work. At this point, we are fully locked into AWS and ap-southeast-2 is our mothership. I am rolling with the big boys, so it is about time I learned how to play the game and get in line.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"While we at work don''t have any reason to deploy things in North Virginia, if there was ever a Sydney or Auckland outage we would be pretty fucked. We rely on all the popular AWS products and it makes sense - I really like using most of them in isolation like DynamoDB, Lambdas and so on. But when you start to abstract away literally everything into a million pieces, and then need a literal certification to be able to understand the 4D \"UX\" patterns of AWS then surely something is wrong. There''s no reason given the design of the internet that all these services should have gone out today because a single provider and their load balancer health check had an existential crisis (I am oversimplifying here ... just let me rant lol).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This comment that I saw on Hacker News describes this well in my opinion:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"\"The costs, performance overhead, and complexity of a modern AWS deployment are insane and so out of line with what most companies should be taking on. But hype + microservices + sunk cost, and here we are.\" - Rob Sanheim","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"68fb211d86ce791a46ac0c3a","media":6,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Seems like a catch-22 in my mind. I can see the appeal of AWS scale if you as a business/company reach a certain scale - that yummy elastic compute makes a lot of sense. At the same time, at that same size the costs on your public clouds like AWS/GCP/Azure etc start to get insanely expensive. Just look at someone like 37 Signals / DHH, who has saved approximately $3.2 million USD moving from AWS to bare-metal, and did not experience any downtime because of a hiccup in North Virginia ...","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'North Virginia is for lovers (of cascading failures)', NULL, 'I dropped the us-east-1 basket and broke all the eggs', '2025-10-20T11:00:00.000Z', 1, 'north-virginia-is-for-lovers-of-cascading-failures', '2025-10-24T06:49:13.596Z', '2025-10-24T06:44:24.364Z', 'draft', '2025-10-24T06:44:43.251Z', '2025-10-24T06:49:13.596Z', 0, 1);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (13, 5, 'North Virginia is for lovers (of cascading failures)', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"So chances are you have already read about this, but from about 9pm last night I began to experience issues with logging into a bunch of services online. Turns out it was the early signs of what would become a major outage with the us-east-1 AWS region that would take out a bunch of different popular services (including Strapi Cloud, which I use for this blog lol).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It''s made me reflect on AWS as a whole. I''ve been learning about different AWS products and microservice architectures in general over the past year, as this is our primary approach with the tools and services we write at work. At this point, we are fully locked into AWS and ap-southeast-2 is our mothership. I am rolling with the big boys, so it is about time I learned how to play the game and get in line.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"While we at work don''t have any reason to deploy things in North Virginia, if there was ever a Sydney or Auckland outage we would be pretty fucked. We rely on all the popular AWS products and it makes sense - I really like using most of them in isolation like DynamoDB, Lambdas and so on. But when you start to abstract away literally everything into a million pieces, and then need a literal certification to be able to understand the 4D \"UX\" patterns of AWS then surely something is wrong. There''s no reason given the design of the internet that all these services should have gone out today because a single provider and their load balancer health check had an existential crisis (I am oversimplifying here ... just let me rant lol).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This comment that I saw on Hacker News describes this well in my opinion:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"\"The costs, performance overhead, and complexity of a modern AWS deployment are insane and so out of line with what most companies should be taking on. But hype + microservices + sunk cost, and here we are.\" - Rob Sanheim","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"68fb211d86ce791a46ac0c3a","media":6,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Seems like a catch-22 in my mind. I can see the appeal of AWS scale if you as a business/company reach a certain scale - that yummy elastic compute makes a lot of sense. At the same time, at that same size the costs on your public clouds like AWS/GCP/Azure etc start to get insanely expensive. Just look at someone like 37 Signals / DHH, who has saved approximately $3.2 million USD moving from AWS to bare-metal, and did not experience any downtime because of a hiccup in North Virginia ...","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'North Virginia is for lovers (of cascading failures)', NULL, 'I dropped the us-east-1 basket and broke all the eggs', '2025-10-20T11:00:00.000Z', 0, 'north-virginia-is-for-lovers-of-cascading-failures', '2025-10-24T06:49:19.571Z', '2025-10-24T06:44:24.364Z', 'published', '2025-10-24T06:49:20.366Z', '2025-10-24T06:49:20.366Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (14, 6, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2025-10-24T06:51:06.614Z', '2025-10-24T06:51:06.614Z', 'draft', '2025-10-24T06:51:07.016Z', '2025-10-24T06:51:07.016Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (15, 6, 'Yet another rewrite', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I’ve migrated my site yet again 😬","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This marks maybe the fifth or sixth iteration of me migrating to a new personal site stack in recent memory. When I was in university I used to have a Wordpress instance running on a Hetzner VPS, and then more recently used a wide range of serverless providers and static site generators from Jekyll, Choo, 11ty, and so on.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Late last year I had migrated to Next.js, as I had already been using it a lot at work and wanted to some more “flashy” things with my site. SSR, ISR, suspense boundaries, different API routes, and everything but the kitchen sink.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I really enjoyed making it my own, but to be honest it got a bit out of control. I was piling on features like a custom are.na client and loader that I would only use in a single page, which I’d only done as it was fun to make and interesting at the time but ultimately ended up becoming tech debt.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I did a major refactor earlier this year to try and get things under control, but I was still really unhappy with it. My site, which is meant to be my own little personal sandpit or “garden”, ended up being just a technical exercise. A dev might find it mildly interesting if they went through the repo, but beyond that I felt it had begun to lack what made my previous endeavours special: content.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Whether that’s blog posts/ramblings like this one, or small creative experiments I work on and publish in my spare time, I feel like it is important to have fun with this kind of thing. It is the content and work that should be the driving force - the tech stack could be literally a public Google Doc, it doesn’t really matter if it is for yourself.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"So, this new migration is an attempt at doing something a bit different. This site is running on SolidStart, a full stack framework built on Solid.js. It is still very new but quite simple and has a React-like syntax (while not having the same foot guns), so I’m trying to keep things fairly bare. In hindsight, it probably would have made more sense for me to go with something like Astro since it is very content driven, but 🤷","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Rather than using a Git-based CMS like Keystatic or Tina which I used on my old site, I’ve opted for a Strapi backend that serves this content via a standard RESTful API. Again, all very vanilla and nothing super custom.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I want to write and make more, and post on here like a madman. I’ve got posts that go back over 4-5 years here, but there are massive gaps and sections where I felt I was being a bit lazy with my writing. I’ve definitely neglected creative pursuits and making things, feeling as though my spare time needed to be used for something that would (in)directly translate to me becoming a better developer, but now I think I realise that’s a bit sad and naff.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Here’s to keeping at it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Yet another rewrite', NULL, 'I migrated my site yet again', NULL, 1, 'yet-another-rewrite', '2025-10-24T06:51:49.454Z', '2025-10-24T06:51:06.614Z', 'draft', '2025-10-24T06:51:31.292Z', '2025-10-24T06:51:49.454Z', 0, 1);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (16, 6, 'Yet another rewrite', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I’ve migrated my site yet again 😬","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This marks maybe the fifth or sixth iteration of me migrating to a new personal site stack in recent memory. When I was in university I used to have a Wordpress instance running on a Hetzner VPS, and then more recently used a wide range of serverless providers and static site generators from Jekyll, Choo, 11ty, and so on.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Late last year I had migrated to Next.js, as I had already been using it a lot at work and wanted to some more “flashy” things with my site. SSR, ISR, suspense boundaries, different API routes, and everything but the kitchen sink.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I really enjoyed making it my own, but to be honest it got a bit out of control. I was piling on features like a custom are.na client and loader that I would only use in a single page, which I’d only done as it was fun to make and interesting at the time but ultimately ended up becoming tech debt.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I did a major refactor earlier this year to try and get things under control, but I was still really unhappy with it. My site, which is meant to be my own little personal sandpit or “garden”, ended up being just a technical exercise. A dev might find it mildly interesting if they went through the repo, but beyond that I felt it had begun to lack what made my previous endeavours special: content.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Whether that’s blog posts/ramblings like this one, or small creative experiments I work on and publish in my spare time, I feel like it is important to have fun with this kind of thing. It is the content and work that should be the driving force - the tech stack could be literally a public Google Doc, it doesn’t really matter if it is for yourself.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"So, this new migration is an attempt at doing something a bit different. This site is running on SolidStart, a full stack framework built on Solid.js. It is still very new but quite simple and has a React-like syntax (while not having the same foot guns), so I’m trying to keep things fairly bare. In hindsight, it probably would have made more sense for me to go with something like Astro since it is very content driven, but 🤷","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Rather than using a Git-based CMS like Keystatic or Tina which I used on my old site, I’ve opted for a Strapi backend that serves this content via a standard RESTful API. Again, all very vanilla and nothing super custom.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I want to write and make more, and post on here like a madman. I’ve got posts that go back over 4-5 years here, but there are massive gaps and sections where I felt I was being a bit lazy with my writing. I’ve definitely neglected creative pursuits and making things, feeling as though my spare time needed to be used for something that would (in)directly translate to me becoming a better developer, but now I think I realise that’s a bit sad and naff.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Here’s to keeping at it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Yet another rewrite', NULL, 'I migrated my site yet again', '2025-10-12T11:00:00.000Z', 0, 'yet-another-rewrite', '2025-10-24T06:51:59.686Z', '2025-10-24T06:51:06.614Z', 'published', '2025-10-24T06:52:00.489Z', '2025-10-24T06:52:00.489Z', 1, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (17, 7, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2025-10-24T06:52:30.525Z', '2025-10-24T06:52:30.525Z', 'draft', '2025-10-24T06:52:30.923Z', '2025-10-24T06:52:30.923Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (18, 7, 'Bullish on Better Auth', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I don’t enjoying dealing with auth.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I haven’t had a great deal of experience implementing this in any projects, but I’ve used Clerk, Stack Auth, and Auth.js in the past.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Each of these solutions came with their own pros and cons. For example, Clerk made it super easy to bootstrap auth with social logins, 2FA, magic keys etc, but comes at the cost of yet another service you need to pay for, and also trusting them with your user info on their infra.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Stack Auth is actually very decent - almost as easy as Clerk whilst also being cheaper and FOSS, so there’s less vendor lock in. However, you are still having to pay them if you use their cloud, and if you’re self hosting then there are better options available.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Better like Better Auth (lol). 2FA, SSO, social logins, magic keys, passwordless login, rate limiting built in - it’s literally got it all","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Also - their docs are some of the best I’ve come across (as far as Typescript projects are concerned). It blows the Auth.js/NextAuth docs out of the water - you can read everything and get a pretty good understanding of what it can do in an afternoon. Their core features are solid, and can easily be extended with plugins that connect to your main auth.ts file.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Better Auth goes as far as dealing with user roles, teams and organisations. I’m currently working on a project at my day job which uses Cognito and user roles/types defined by hand. It is incredibly complex to write and follow, and makes me want to compare against Better Auth for implementation and complexity.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"If you haven’t given it a try yet, give it a go!","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Bullish on Better Auth', NULL, 'I don''t enjoy dealiing with auth.', NULL, 1, 'bullish-on-better-auth', '2025-10-24T06:53:17.250Z', '2025-10-24T06:52:30.525Z', 'draft', '2025-10-24T06:53:17.250Z', '2025-10-24T06:53:17.250Z', 0, 1);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (19, 7, 'Bullish on Better Auth', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I don’t enjoying dealing with auth.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I haven’t had a great deal of experience implementing this in any projects, but I’ve used Clerk, Stack Auth, and Auth.js in the past.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Each of these solutions came with their own pros and cons. For example, Clerk made it super easy to bootstrap auth with social logins, 2FA, magic keys etc, but comes at the cost of yet another service you need to pay for, and also trusting them with your user info on their infra.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Stack Auth is actually very decent - almost as easy as Clerk whilst also being cheaper and FOSS, so there’s less vendor lock in. However, you are still having to pay them if you use their cloud, and if you’re self hosting then there are better options available.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Better like Better Auth (lol). 2FA, SSO, social logins, magic keys, passwordless login, rate limiting built in - it’s literally got it all","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Also - their docs are some of the best I’ve come across (as far as Typescript projects are concerned). It blows the Auth.js/NextAuth docs out of the water - you can read everything and get a pretty good understanding of what it can do in an afternoon. Their core features are solid, and can easily be extended with plugins that connect to your main auth.ts file.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Better Auth goes as far as dealing with user roles, teams and organisations. I’m currently working on a project at my day job which uses Cognito and user roles/types defined by hand. It is incredibly complex to write and follow, and makes me want to compare against Better Auth for implementation and complexity.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"If you haven’t given it a try yet, give it a go!","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Bullish on Better Auth', NULL, 'I don''t enjoy dealiing with auth.', '2025-06-03T12:00:00.000Z', 0, 'bullish-on-better-auth', '2025-10-24T06:53:41.286Z', '2025-10-24T06:52:30.525Z', 'published', '2025-10-24T06:53:42.092Z', '2025-10-24T06:53:42.092Z', 1, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (21, 9, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2025-10-24T06:54:49.282Z', '2025-10-24T06:54:49.282Z', 'draft', '2025-10-24T06:54:49.683Z', '2025-10-24T06:54:49.683Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (22, 9, 'On the idea of a creative design system', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"One of the things we do at work we writing new UI components is create unit tests and stories to validate + illustrate the functionality of what we’ve created.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"It works well as a process, since it forces us to think about how components could be reused across different apps and not have it defined by specific business logic. This encourages components to be reused in the future, rather than having to reinvent the wheel with each new project.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"There are many mature examples of this in different design systems. Polaris by Shopify is one such example, which is still tightly coupled with Shopify as a product but allows anyone to see each component as a sum of smaller pieces. Something like Polaris has a tight, consistent design because of this, and you can feel how each component has had a lot of thought and effort behind it.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I hadn’t known about this approach until recently, which is known by some as “atomic design”. When I was learning about UI and UX a few years back, I genuinely thought that designs systems were born out of a product, not the other way round. You would design your product first, then break it down to the component level to create your design system.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Looking at what I used to do when designing apps or tools, it seems crazy to me that I wasn’t doing this. It makes so much sense from a consistency and development point of view, and it’s evident in my early work that this was affecting me (although at the time I did not know this).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I love the idea of developing a mini design system that I can utilise for various web projects. I feel as though having the added restriction of only being able to use a select set of components would actually open up a lot of creative possibilities, and would also (hopefully) result in me being able to finish things faster.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Let’s see how it goes.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'On the idea of a creative design system', NULL, 'Thinking about ways to test my components in isolation.', NULL, 1, 'on-the-idea-of-a-creative-design-system', '2025-10-24T06:55:48.840Z', '2025-10-24T06:54:49.282Z', 'draft', '2025-10-24T06:55:10.478Z', '2025-10-24T06:55:48.840Z', 0, 1);
