INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (62, 19, 'Tell them I said no', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"6900933300f0998219e0d492","media":17,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"block","fields":{"id":"6903112d5eb6b167b541f6b7","style":"info","content":{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Hello!","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}},"blockName":"","blockType":"banner"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am currently reading the book “Tell Them I Said No” by Martin Herbert, which is a collection of essays regarding different artists who have deliberately withdrawn from the art world (or, as I liked to think of it as ”the supermarket”). ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I’m only a fraction of the way through it but it is a beautiful read. I really wish that my younger self could have come across this book while still at art school and trying to reckon with “playing the game”, at least in New Zealand. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This book came out in late 2016. At that time, I was still working and making collaboratively, and had a made few “successful” works that both pissed a lot of people off as well as registered commercial interest. We didn’t really know what we were doing, but I think there was a lot of naivety and arrogance on our part thinking that this balance of making engaging work and making money was “easy”.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"We got really far, but ultimately I found out the hard way that this world wasn’t really for me and I turned away from it completely. Since then I have made a few small things here and there, but have largely turned my back on making from the hurt that I experienced when I was younger. I said yes to a lot of things which I probably should’ve said no, but I suppose that is the benefit of hindsight.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Things might have turned out a bit differently if I had read this book in 2016. I could have learned about how someone like David Hammons had dealt with similar issues - that you can step back from all the nonsense but continue to engage in a critical and meaningful way without selling yourself away. You don’t have to give up on making completely, and if anything poke fun at the enormous power imbalance that exists in the industry (and probably always will).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6900971c36105819bbe45c4b","media":18,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"At this point I don’t know if I will ever engage in the art world ever again, or even try to make “art” in the same way. I’ll probably always be working on small things, but never for the purpose of a gallery circuit or something similar. I used to feel quite cut about this but I think I’ve found other things to occupy myself. The art world and its creatures helped me learn about different things that have shaped how I conduct myself in a broader sense which has probably been the most productive thing. If anything, it actually taught me very little about art making lol.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Tell them I said no', NULL, 'A book I should have read years ago. ', '2025-10-28T09:00:00.000Z', 0, 'tell-them-i-said-no', '2025-10-30T07:19:02.037Z', '2025-10-28T09:55:08.009Z', 'published', '2025-10-30T07:19:02.856Z', '2025-10-30T07:19:02.856Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (63, 19, 'Tell them I said no', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"6900933300f0998219e0d492","media":17,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am currently reading the book “Tell Them I Said No” by Martin Herbert, which is a collection of essays regarding different artists who have deliberately withdrawn from the art world (or, as I liked to think of it as ”the supermarket”). ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I’m only a fraction of the way through it but it is a beautiful read. I really wish that my younger self could have come across this book while still at art school and trying to reckon with “playing the game”, at least in New Zealand. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This book came out in late 2016. At that time, I was still working and making collaboratively, and had a made few “successful” works that both pissed a lot of people off as well as registered commercial interest. We didn’t really know what we were doing, but I think there was a lot of naivety and arrogance on our part thinking that this balance of making engaging work and making money was “easy”.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"We got really far, but ultimately I found out the hard way that this world wasn’t really for me and I turned away from it completely. Since then I have made a few small things here and there, but have largely turned my back on making from the hurt that I experienced when I was younger. I said yes to a lot of things which I probably should’ve said no, but I suppose that is the benefit of hindsight.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Things might have turned out a bit differently if I had read this book in 2016. I could have learned about how someone like David Hammons had dealt with similar issues - that you can step back from all the nonsense but continue to engage in a critical and meaningful way without selling yourself away. You don’t have to give up on making completely, and if anything poke fun at the enormous power imbalance that exists in the industry (and probably always will).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6900971c36105819bbe45c4b","media":18,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"At this point I don’t know if I will ever engage in the art world ever again, or even try to make “art” in the same way. I’ll probably always be working on small things, but never for the purpose of a gallery circuit or something similar. I used to feel quite cut about this but I think I’ve found other things to occupy myself. The art world and its creatures helped me learn about different things that have shaped how I conduct myself in a broader sense which has probably been the most productive thing. If anything, it actually taught me very little about art making lol.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Tell them I said no', NULL, 'A book I should have read years ago. ', '2025-10-28T09:00:00.000Z', 0, 'tell-them-i-said-no', '2025-10-30T07:48:29.863Z', '2025-10-28T09:55:08.009Z', 'published', '2025-10-30T07:48:30.705Z', '2025-10-30T07:48:30.705Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (64, 19, 'Tell them I said no', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"6900933300f0998219e0d492","media":17,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"block","fields":{"id":"690319205eb6b167b541f6b8","style":"info","content":{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This is a bit of a whing","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}},"blockName":"","blockType":"banner"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am currently reading the book “Tell Them I Said No” by Martin Herbert, which is a collection of essays regarding different artists who have deliberately withdrawn from the art world (or, as I liked to think of it as ”the supermarket”). ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I’m only a fraction of the way through it but it is a beautiful read. I really wish that my younger self could have come across this book while still at art school and trying to reckon with “playing the game”, at least in New Zealand. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This book came out in late 2016. At that time, I was still working and making collaboratively, and had a made few “successful” works that both pissed a lot of people off as well as registered commercial interest. We didn’t really know what we were doing, but I think there was a lot of naivety and arrogance on our part thinking that this balance of making engaging work and making money was “easy”.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"We got really far, but ultimately I found out the hard way that this world wasn’t really for me and I turned away from it completely. Since then I have made a few small things here and there, but have largely turned my back on making from the hurt that I experienced when I was younger. I said yes to a lot of things which I probably should’ve said no, but I suppose that is the benefit of hindsight.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Things might have turned out a bit differently if I had read this book in 2016. I could have learned about how someone like David Hammons had dealt with similar issues - that you can step back from all the nonsense but continue to engage in a critical and meaningful way without selling yourself away. You don’t have to give up on making completely, and if anything poke fun at the enormous power imbalance that exists in the industry (and probably always will).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6900971c36105819bbe45c4b","media":18,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"At this point I don’t know if I will ever engage in the art world ever again, or even try to make “art” in the same way. I’ll probably always be working on small things, but never for the purpose of a gallery circuit or something similar. I used to feel quite cut about this but I think I’ve found other things to occupy myself. The art world and its creatures helped me learn about different things that have shaped how I conduct myself in a broader sense which has probably been the most productive thing. If anything, it actually taught me very little about art making lol.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Tell them I said no', NULL, 'A book I should have read years ago. ', '2025-10-28T09:00:00.000Z', 0, 'tell-them-i-said-no', '2025-10-30T07:52:27.058Z', '2025-10-28T09:55:08.009Z', 'draft', '2025-10-30T07:52:11.692Z', '2025-10-30T07:52:27.058Z', 0, 1);
