,"newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"follow the steps outlined in my MCP package doc","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":". You should be able to add and interact with this using any modern editor or agent so long as you have Node installed. Despite it saying you need an API key this is not required at least at the moment, although it might change in the future if I start needing to serve more data sources (or things start getting costly). Otherwise, maybe try making your own!","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Stainless is amazing', NULL, '', '2025-11-27T03:00:00.000Z', 0, 'stainless-is-amazing', '2025-11-27T03:25:54.441Z', '2025-11-27T02:41:16.042Z', 'draft', '2025-11-27T03:25:31.182Z', '2025-11-27T03:25:54.441Z', 0, 1);
