Style":"","textFormat":0},{"type":"block","fields":{"id":"69643036939c257c033c3d8e","media":27,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This combined approach feels to me like a good compromise between a standard, single prompt input, and the hugely expensive ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"696430ec58fa22ce54c212d6","type":"link","fields":{"url":"https://venturebeat.com/technology/how-ralph-wiggum-went-from-the-simpsons-to-the-biggest-name-in-ai-right-now","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Ralph Wiggum approach","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" that seems to be all the rage on Twitter at the moment. Potentially, if you are trying to think of different approaches to solving a problem this technique could produce something novel (or at least something you might not have thought of initially).","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am trying to take all of this stuff with a grain of salt still since LLMs can still make catastrophic mistakes (and doesn''t really understand what it is doing), but tools like this can definitely help to flatten the feedback loop.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Using agents in Opencode', NULL, 'Experimenting with parallel (sub)agents for rapid reviews', '2026-01-11T22:00:00.000Z', 0, 'using-agents-in-opencode', '2026-01-11T23:46:02.704Z', '2026-01-11T23:00:01.755Z', 'published', '2026-01-11T23:46:02.728Z', '2026-01-11T23:46:02.728Z', 1, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (94, 26, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2026-01-20T00:25:55.555Z', '2026-01-20T00:25:55.554Z', 'draft', '2026-01-20T00:25:55.622Z', '2026-01-20T00:25:55.622Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (95, 26, 'I still feel like an imposter', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"696ed00799adc8b038ad9101","style":"info","content":{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This is another whinge post, sorry","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}},"blockName":"","blockType":"banner"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''ve been professionally working as a software engineer now for 11 months. When I started I very much felt like an imposter, but that was somewhat to be expected given that I didn''t come from a traditional computer science or technology background, so figured the feeling would begin to go away after a few months of learning and general work experience. I thought so long as I stay on top of things it would begin to feel a bit easier/natural for me.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Truth is, that really hasn''t been the case. If anything it has gotten harder. I can''t even really Dunning-Kruger myself, because as soon as I feel like I am getting the hang of something I get hit in the face with shit lol. Every day I feel like I begin unravelling something as part of my job or personal projects, and in doing so I uncover 5+ things that I know absolutely nothing about and don''t even know where to start.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"When I was a teacher, it was a similar feeling in the beginning but the good ol'' \"fake it ''til you make it\" mantra actually applied here. I got to a point after roughly a year where I didn''t need to fake it anymore and I had confidence in the classroom. But with SWE, I feel like this mantra just doesn''t work and if anything will continually bite you in the arse. AI/LLMs make it seem like it''s so easy to pick things up quickly, as though you are inserting those knowledge cartridge things like Neo in the Matrix, but by the time you have finished verifying its bullshit it''s probably taken three times as long as reading a book or something, and your mental load is fucked. You have to be continually asking questions, big and small, in order to be fully confident that you understand something, but in a work environment I don''t believe this isn''t necessarily possible.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Despite all this time and the best LLMs at my disposable, the reality is that I still feel like a fraud and an imposter. I still suck as DSA, my system design knowledge is limited at best, and I just really struggle to be confident in my work. I''m second guessing everything that I write/make, like there''s nowhere to hide, no magic or mystery, and I just feel embarrassed. It is really hard to keep pushing myself whilst being in this mindset. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''m curious to know if there are others who feel a similar way. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'I still feel like an imposter', NULL, 'The more I learn, the uncertainty seems to follow', '2026-01-19T23:30:00.000Z', 1, 'i-still-feel-like-an-imposter', '2026-01-20T00:50:37.750Z', '2026-01-20T00:25:55.554Z', 'draft', '2026-01-20T00:26:28.769Z', '2026-01-20T00:50:37.750Z', 0, 1);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (96, 26, 'I still feel like an imposter', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"696ed00799adc8b038ad9101","style":"info","content":{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"This is another whinge post, sorry","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}},"blockName":"","blockType":"banner"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''ve been professionally working as a software engineer now for 11 months. When I started I very much felt like an imposter, but that was somewhat to be expected given that I didn''t come from a traditional computer science or technology background, so figured the feeling would begin to go away after a few months of learning and general work experience. I thought so long as I stay on top of things it would begin to feel a bit easier/natural for me.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Truth is, that really hasn''t been the case. If anything it has gotten harder. I can''t even really Dunning-Kruger myself, because as soon as I feel like I am getting the hang of something I get hit in the face with shit lol. Every day I feel like I begin unravelling something as part of my job or personal projects, and in doing so I uncover 5+ things that I know absolutely nothing about and don''t even know where to start.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"When I was a teacher, it was a similar feeling in the beginning but the good ol'' \"fake it ''til you make it\" mantra actually applied here. I got to a point after roughly a year where I didn''t need to fake it anymore and I had confidence in the classroom. But with SWE, I feel like this mantra just doesn''t work and if anything will continually bite you in the arse. AI/LLMs make it seem like it''s so easy to pick things up quickly, as though you are inserting those knowledge cartridge things like Neo in the Matrix, but by the time you have finished verifying its bullshit it''s probably taken three times as long as reading a book or something, and your mental load is fucked. You have to be continually asking questions, big and small, in order to be fully confident that you understand something, but in a work environment I don''t believe this isn''t necessarily possible.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Despite all this time and the best LLMs at my disposable, the reality is that I still feel like a fraud and an imposter. I still suck as DSA, my system design knowledge is limited at best, and I just really struggle to be confident in my work. I''m second guessing everything that I write/make, like there''s nowhere to hide, no magic or mystery, and I just feel embarrassed. It is really hard to keep pushing myself whilst being in this mindset. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I''m curious to know if there are others who feel a similar way. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'I still feel like an imposter', NULL, 'The more I learn, the uncertainty seems to follow', '2026-01-19T23:30:00.000Z', 0, 'i-still-feel-like-an-imposter', '2026-01-20T00:50:41.746Z', '2026-01-20T00:25:55.554Z', 'published', '2026-01-20T00:50:41.781Z', '2026-01-20T00:50:41.781Z', 1, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (97, 27, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2026-01-26T00:03:57.197Z', '2026-01-26T00:03:57.197Z', 'draft', '2026-01-26T00:03:57.231Z', '2026-01-26T00:03:57.231Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (98, 27, 'Clawdbot is kind of insane', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"In my Twitter/X echo chamber over the weekend, I''ve been witnessing some of the craziest stuff being posted by tech/dev accounts with regards to ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b34c53858267e3d17d85","type":"link","fields":{"url":"https://clawd.bot/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Clawdbot","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", which I like to think of as being like ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b33953858267e3d17d84","type":"link","fields":{"url":"https://claude.com/blog/cowork-research-preview","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Claude Cowork","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" but for your entire life and very much targeted at developers.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"For context, Clawdbot runs on your machine like a Linux VPS and opens a gateway via Whatsapp, Discord, Telegram et al that you can chat via. It has skills and plugins similar to Claude Code, only you are essentially giving it complete unfettered access to your machine, logins (if you enable this), web searches (via the Brave Search API), and so on. Most people are running this using hosted models like Claude, GPT, Gemini etc, but technically it can support local models via Ollama.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Now this seems pretty cool in theory, as you are creating your own virtual assistant like Siri that is far more capable with access to real tools, but digging deeper there were a couple of weird things that I noticed.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People buying Mac Minis for the sole purpose of running Clawdbot","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". These machines (at least in New Zealand) are over $1,000 for the base model. While Clawdbot is somewhat resource intensive on paper, most people have gotten cheap VPSs or disused laptops running fine. The only differentiator would be the ability to use iMessage as a bridge on a native macOS machine, but this seems extreme given that the manner in which you interface with Clawdbot (chat, or sometimes voice) is basically the same across all providers. Even the author of Clawdbot pointed out ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b3be53858267e3d17d86","type":"link","fields":{"url":"https://x.com/clawdbot/status/2015265005210353824?s=46","linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"this is kind of stupid","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" lol.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People not securing their ports","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". Clawdbot uses port 18789 by default for its gateway. Luic Catacora from Replicate pointed out that ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b3e053858267e3d17d87","type":"link","fields":{"url":"https://x.com/lucatac0/status/2015473205863948714","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"many people have insecure config for their Clawdbot setups","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", meaning that gateways are completely exposed publicly on services like Shodan:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6976b23853858267e3d17d82","media":28,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People will have API keys stored here for Google Workspace, Anthropic, OpenAI, full shell access and browser automation. A recipe to get pwned and have a very, very bad day.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People sharing personal data with AI labs","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". I mean most people already do this and get ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b32253858267e3d17d83","type":"link","fields":{"url":"https://en.wikipedia.org/wiki/Chatbot_psychosis","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"oneshotted via a ChatGPT psychosis","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", but willingly giving access to your browser and emails seems like the next step surely lol. I wouldn''t really want all of my emailed invoices etc as part of Sam Altman''s next training data batch, but maybe others have resigned to that fact. Having them train off your company code is one thing, but then giving it access to the rest of your life is a bit much...","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":1},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I don''t want to give off the impression that I hate the project or anything. I think it''s a cool example of FOSS software going the extra mile in competing with proprietary alternatives (in this case Cowork), and the fact that ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b47e53858267e3d17d88","type":"link","fields":{"url":"https://steipete.me/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Peter Steinberger","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" (the author) open-sourced it is awesome. This is a very powerful tool, and it isn''t necessarily the fault of the tool if people decide to be a bit silly with it (the same would apply to Cowork). But, I do think it reflects on how powerful the current AI/LLM hype cycle is, such that even the most experienced developers will decide to YOLO their security to run a potentially unsecured LLM and webserver on their machine.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null,"textFormat":1}}', 'Clawdbot is kind of insane', NULL, 'It''s a friendly looking crustacean, but careful! It might bite you in the arse.', NULL, 1, 'clawdbot-is-kind-of-insane', '2026-01-26T00:34:56.445Z', '2026-01-26T00:03:57.197Z', 'draft', '2026-01-26T00:04:13.935Z', '2026-01-26T00:34:56.445Z', 0, 1);
