ction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null,"textFormat":1}}', 'Clawdbot is kind of insane', NULL, 'It''s a friendly looking crustacean, but careful! It might bite you in the arse', '2026-01-25T23:30:00.000Z', 0, 'clawdbot-is-kind-of-insane', '2026-01-26T00:39:10.933Z', '2026-01-26T00:03:57.197Z', 'published', '2026-01-26T00:39:10.944Z', '2026-01-26T00:39:10.944Z', 0, 0);
