INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (102, 27, 'Clawdbot is kind of insane', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"In my Twitter/X echo chamber over the weekend, I''ve been witnessing some of the craziest stuff being posted by tech/dev accounts with regards to ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b34c53858267e3d17d85","type":"link","fields":{"url":"https://clawd.bot/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Clawdbot","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", which I like to think of as being like ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b33953858267e3d17d84","type":"link","fields":{"url":"https://claude.com/blog/cowork-research-preview","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Claude Cowork","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" but for your entire life and very much targeted at developers.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"For context, Clawdbot runs on your machine like a Linux VPS and opens a gateway via Whatsapp, Discord, Telegram et al that you can chat via. It has skills and plugins similar to Claude Code, only you are essentially giving it complete unfettered access to your machine, logins (if you enable this), web searches (via the Brave Search API), and so on. Most people are running this using hosted models like Claude, GPT, Gemini etc, but technically it can support local models via Ollama.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Now this seems pretty cool in theory, as you are creating your own virtual assistant like Siri that is far more capable with access to real tools, but digging deeper there were a couple of weird things that I noticed.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6976b83da5a2f705d3ab4b33","media":29,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People buying Mac Minis for the sole purpose of running Clawdbot","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". These machines (at least in New Zealand) are over $1,000 for the base model. While Clawdbot is somewhat resource intensive on paper, most people have gotten cheap VPSs or disused laptops running fine. The only differentiator would be the ability to use iMessage as a bridge on a native macOS machine, but this seems extreme given that the manner in which you interface with Clawdbot (chat, or sometimes voice) is basically the same across all providers. Even the author of Clawdbot pointed out ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b3be53858267e3d17d86","type":"link","fields":{"url":"https://x.com/clawdbot/status/2015265005210353824?s=46","linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"this is kind of stupid","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" lol.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":1},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People not securing their ports","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". Clawdbot uses port 18789 by default for its gateway. Luic Catacora from Replicate pointed out that ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b3e053858267e3d17d87","type":"link","fields":{"url":"https://x.com/lucatac0/status/2015473205863948714","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"many people have insecure config for their Clawdbot setups","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", meaning that gateways are completely exposed publicly on services like Shodan:","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"6976b23853858267e3d17d82","media":28,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People will have API keys stored here for Google Workspace, Anthropic, OpenAI, full shell access and browser automation. A recipe to get pwned and have a very, very bad day.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"People sharing personal data with AI labs","type":"text","style":"","detail":0,"format":1,"version":1},{"mode":"normal","text":". I mean most people already do this and get ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b32253858267e3d17d83","type":"link","fields":{"url":"https://en.wikipedia.org/wiki/Chatbot_psychosis","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"oneshotted via a ChatGPT psychosis","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", but willingly giving access to your browser and emails seems like the next step surely lol. I wouldn''t really want all of my emailed invoices etc as part of Sam Altman''s next training data batch, but maybe others have resigned to that fact. Having them train off your company code is one thing, but then giving it access to the rest of your life is a bit much...","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I don''t want to give off the impression that I hate the project or anything. I think it''s a cool example of FOSS software going the extra mile in competing with proprietary alternatives (in this case Cowork), and the fact that ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"6976b47e53858267e3d17d88","type":"link","fields":{"url":"https://steipete.me/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Peter Steinberger","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" (the author) open-sourced it is awesome. This is a very powerful tool, and it isn''t necessarily the fault of the tool if people decide to be a bit silly with it (the same would apply to Cowork). But, I do think it reflects on how powerful the current AI/LLM hype cycle is, such that even the most experienced developers will decide to YOLO their security to run a potentially unsecured LLM and webserver on their machine.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null,"textFormat":1}}', 'Clawdbot is kind of insane', NULL, 'It''s a friendly looking crustacean, but careful! It might bite you in the arse', '2026-01-25T23:30:00.000Z', 0, 'clawdbot-is-kind-of-insane', '2026-01-26T00:43:19.140Z', '2026-01-26T00:03:57.197Z', 'published', '2026-01-26T00:43:19.160Z', '2026-01-26T00:43:19.160Z', 1, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (103, 28, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2026-02-06T07:30:19.116Z', '2026-02-06T07:30:19.115Z', 'draft', '2026-02-06T07:30:19.188Z', '2026-02-06T07:30:19.188Z', 0, 0);
INSERT INTO "_posts_v" ("id", "parent_id", "version_title", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (104, 28, 'AI is making me anxious and stupid', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"I’ve been at a bit of a loss since the start of this year. Since Opus 4.5, LLMs including open weight models such as Kimi 2.5 and GLM 4.7 have (in my opinion) gotten incredibly good. While each release and improvement now is only incremental, the tooling and ecosystem around models is ever changing. The moat now isn’t who has the best model since they are all really good, but the tooling that you build around it (e.g. proprietary à la Claude Code or something FOSS like OpenCode). ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"Keeping up with these developments is exhausting even if you’re fairly terminally “tapped in” online. Apparently MCPs are so last year and skills are the new thing? If you don’t have an AGENTS.md, cursor rules file, parallel subagents running in sandboxed Hetzner VPS instances using multiple models with git worktrees that is split across different domains you’re not gonna make it bro /s. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"In all seriousness, I’ve been trying my best to keep up and give it a proper shot whilst still trying to “git gud” at things that traditionally make a solid engineer. People online will often talk about how important it is to have a solid understanding of the fundamentals so that you can drive LLMs correctly, and you don’t become overly reliant on them for everything that you build. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"But using AI feels genuinely addictive. It has become to easy to prompt an agent even for the easiest tasks because it is technically easier (although this is 50/50, since models still can fuck up in hilarious ways causing you to take twice as long as if you were to do it manually). With an overly confident Claude or Codex, you feel as though you can learn anything and pick anything up instantly, and that this must be true because that’s what all the cool kids on Twitter are saying. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"The problem is AI hasn’t always accelerated my work or learning. If anything, sometimes I unfortunately find myself trusting its take more than my own gut. Surely Anthropic and OpenAI with ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69887408f08521b4bd8c6ba8","type":"link","fields":{"url":"https://www.reuters.com/technology/anthropics-more-than-20-billion-funding-close-soon-next-week-bloomberg-news-2026-02-07/","newTab":true,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"tens of billions of dollars in funding","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" and some of the best researchers in the world have engineered this model to be smarter than me. I doubt myself, I think I’m a dumbass without Claude, I feel useless without an LLM and I need it to function as a developer. But this isn’t at all true, and if anything I am deliberately making myself (or at the very least making myself feel) stupider than what I actually am because I don’t really have that solid foundational understanding to fall back on. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"69887496f08521b4bd8c6ba9","media":30,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"If anything, perhaps LLMs have highlighted the “Mr. Clumsy” nature in me. For context, Mr. Clumsy is a character from Roger Hargreaves excellent “Mr. Men” series of books, whose anxiety and nervousness is causing them to always doubt their own ability. Claude brings out the Mr. Clumsy in me as it accelerates my anxiety of “getting it right” the first time and not giving myself the chance to fail in a spectacular way. Mr. Clumsy gets frustrated at the feeling of being incapable of doing basic tasks, trusting your own ability to think, and that’s is maybe what AI has been doing to me. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"I think that I must not be the only Mr. Clumsy developer out there. The cycle is real, and I wouldn’t be surprised if others (particularly juniors to mid level like myself) felt the same way. On the one hand I’m comforted by people like ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69887379f08521b4bd8c6ba4","type":"link","fields":{"url":"https://x.com/gergelyorosz/status/2019123213364764837?s=46","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Grady Booch","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" who believe that similar events like this have happened before and AI won’t ever make us developers fully obsolete, but my ever growing dependence on these models is scaring the shit out of me because I am starting to doubt myself in terms of what I genuinely do know.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"69887512f08521b4bd8c6baa","media":31,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[{"mode":"normal","text":"As a person and developer, I probably need to be more like Mr. Silly from Nonsenseland. In his case, he relentlessly pursuits the “Nonsense Cup”, and is a champion at keeping on. He just keeps on going regardless, much as others probably should despite what AI lab talking head is saying on Twitter or what my own internal Mr. Clumsy is saying. It will likely piss some people off by seeming overconfident and I would like to avoid this where possible, but I don’t want to become totally beholden to the shiny matmul machine. I would hope at many chances of failing but ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"69887379f08521b4bd8c6ba5","type":"link","fields":{"url":"https://en.wikipedia.org/wiki/The_Myth_of_Sisyphus","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"being able to smile","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" as I did than begin to doubt in myself. ","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"block","fields":{"id":"69887560f08521b4bd8c6bab","media":32,"blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"start","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'AI is making me anxious and stupid', NULL, 'Claude … you’re giving me trust issues', '2026-02-08T11:00:00.000Z', 1, 'ai-is-making-me-anxious-and-stupid', '2026-02-08T11:38:53.960Z', '2026-02-06T07:30:19.115Z', 'draft', '2026-02-08T11:29:03.034Z', '2026-02-08T11:38:53.960Z', 0, 1);
