INSERT INTO "_works_v" ("id", "parent_id", "version_title", "version_summary", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (2, 1, 'An idea for a performance', 'A tool for generating performance ideas', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"An idea for a performance is a web experiment and are.na channel that displays random ideas for performances, built using the are.na API.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'An idea for a performance', NULL, 'A tool for generating performance ideas.', '2025-10-22T11:00:00.000Z', 0, 'an-idea-for-a-performance', '2025-10-24T06:57:58.891Z', '2025-10-24T06:56:35.595Z', 'draft', '2025-10-24T06:56:52.435Z', '2025-10-24T06:57:58.891Z', 0, 1);
