INSERT INTO "_works_v" ("id", "parent_id", "version_title", "version_summary", "version_hero_image_id", "version_content", "version_meta_title", "version_meta_image_id", "version_meta_description", "version_published_at", "version_generate_slug", "version_slug", "version_updated_at", "version_created_at", "version__status", "created_at", "updated_at", "latest", "autosave") VALUES (31, 9, 'Te Wāhi Auaha', 'A maker space.', NULL, '{"root":{"type":"root","format":"","indent":0,"version":1,"children":[{"type":"block","fields":{"id":"68fb33aecfd6350854a26b97","blockName":"","blockType":"mediaBlock"},"format":"","version":2},{"type":"paragraph","format":"","indent":0,"version":1,"children":[],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"id":"68fb337acfd6350854a26b91","type":"link","fields":{"url":"https://takapuna.school.nz","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"Takapuna Grammar School (TGS)","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" launched their innovation space in 2020, offering a wide range of tools and machinery for students and staff to use.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I worked at TGS as an art and technology teacher from 2021 - 2023, and together with Robin Kydd helped to rework the space to become Te Wāhi Auaha - the space of making.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"We designed, developed, and deployed ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb337acfd6350854a26b92","type":"link","fields":{"url":"https://learn.tewahi.com","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"a centralized knowledge hub","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":" that exists both online and offline. The hub includes guides for students and staff on using specialised tools and machines, as well as steps to follow for achieving specific goals.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"As part of my work, I developed custom software that students could use as part of their art or technology curriculum, or for their own personal projects. The most notable example is ","type":"text","style":"","detail":0,"format":0,"version":1},{"id":"68fb337acfd6350854a26b93","type":"link","fields":{"url":"https://ar.tewahi.com","newTab":false,"linkType":"custom"},"format":"","indent":0,"version":3,"children":[{"mode":"normal","text":"gARden","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null},{"mode":"normal","text":", a web app that generates a permanent AR view of a 3D model that can be printed, distributed and shared.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"Every Thursday we held an Innovation Workshop, where students could bring in projects that they were working on and get our help in using specialised machines such as laser cutters and 3D printers as part of their making. The group consisted of both junior and senior students, with some seniors having attended the workshop every week since its inception in 2020.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0},{"type":"paragraph","format":"","indent":0,"version":1,"children":[{"mode":"normal","text":"I am proud of the work that we achieved in setting up and running Te Wāhi, particularly as a safe space for students to come and work on creative projects (even if these didn''t fall under an academic/NCEA curriculum). It remains to be the most enjoyable and rewarding part of my teaching experience.","type":"text","style":"","detail":0,"format":0,"version":1}],"direction":null,"textStyle":"","textFormat":0}],"direction":null}}', 'Te Wāhi Auaha', NULL, 'A maker space.', NULL, 1, 'te-whi-auaha', '2025-10-24T08:07:17.245Z', '2025-10-24T08:05:56.461Z', 'draft', '2025-10-24T08:06:12.150Z', '2025-10-24T08:07:17.245Z', 1, 1);
